insert into places (id, city_id, name, name_ja, category, coords, nearest_station, station_walk_min, interest_tags, energy, crowd_level, discovery, signature, physical_demand, duration_taste_min, duration_typical_min, duration_full_min, best_window, crowd_note, worth_it_if, skip_if, local_tip, cost_jpy, booking_req, booking_lead_days, opens_at, closes_at, hours_vary, closed_weekdays, conflicts_with, pairs_with, seasons, sources, verification_status) values
  ('kyt-fushimi-inari', 'kyoto-city', 'Fushimi Inari Taisha', '伏見稲荷大社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7727, 34.9671), 4326)::extensions.geography, 'inari', 2, array['shrines', 'nature']::interest_tag[], 0.45, 0.9, 0.1, 0.95, 0.5, 45, 90, 180, array['before 08:00', 'after 17:30']::text[], '10:00–16:00 the first 300 gates are a shuffling queue. Past the Yotsutsuji viewpoint it empties out almost entirely.', array['early_riser', 'photography']::text[], array['limited_mobility', 'packed_schedule']::text[], 'Open 24 hours and unstaffed at night — the 6am visit is the one people remember. Take the Local from Kyoto Station; the Rapid does not stop at Inari.', 0, 'none', null, null, null, false, array[]::int[], array['kyt-arashiyama-bamboo']::text[], array['kyt-tofukuji']::text[], array[]::text[], array['inari.jp']::text[], 'draft'),
  ('kyt-kiyomizu', 'kyoto-city', 'Kiyomizu-dera', '清水寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.785, 34.9949), 4326)::extensions.geography, 'kiyomizu-gojo', 20, array['shrines', 'history']::interest_tag[], 0.5, 0.95, 0.05, 0.95, 0.5, 45, 90, 120, array['before 08:00']::text[], 'By ten the approach lanes are a slow river of people. At six it is yours, and the wooden stage catches the morning light.', array['photography', 'history']::text[], array['limited_mobility']::text[], 'The uphill walk from the station is the point as much as the temple — Ninenzaka and Sannenzaka are on the way down. Autumn evening illuminations need a separate ticket.', 500, 'none', null, '06:00', '18:00', true, array[]::int[], array[]::text[], array['kyt-ninenzaka']::text[], array['koyo', 'sakura']::text[], array['kiyomizudera.or.jp']::text[], 'draft'),
  ('kyt-ninenzaka', 'kyoto-city', 'Ninenzaka & Sannenzaka', '二年坂・三年坂', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(135.781, 34.9975), 4326)::extensions.geography, 'kiyomizu-gojo', 15, array['history', 'shopping']::interest_tag[], 0.3, 0.8, 0.2, 0.6, null, 30, 75, 120, array[]::text[], 'Busy from mid-morning; empties after the shops shut around six, when it is at its most beautiful.', array[]::text[], array[]::text[], 'No ticket, no hours — this is the slack in a Higashiyama day. Run it long or cut it short. The Starbucks in a machiya is genuinely worth a look.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['kyt-kiyomizu', 'kyt-kodaiji']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-kodaiji', 'kyoto-city', 'Kodai-ji', '高台寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.781, 35.0007), 4326)::extensions.geography, 'kiyomizu-gojo', 15, array['shrines', 'nature']::interest_tag[], 0.3, 0.5, 0.4, 0.6, null, 30, 60, 90, array[]::text[], 'Comfortable even at midday. The autumn night illumination is the exception — queues form.', array[]::text[], array[]::text[], 'Two minutes off Ninenzaka and most people walk past it. The bamboo grove at the back is small but empty, unlike the famous one.', 600, 'none', null, '09:00', '17:30', true, array[]::int[], array[]::text[], array['kyt-ninenzaka']::text[], array['koyo']::text[], array['kodaiji.com']::text[], 'draft'),
  ('kyt-yasaka-shrine', 'kyoto-city', 'Yasaka Shrine', '八坂神社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7787, 35.0037), 4326)::extensions.geography, 'gion-shijo', 5, array['shrines']::interest_tag[], 0.15, 0.7, 0.1, 0.6, null, 15, 30, 45, array[]::text[], 'Always people, never a queue — it is a thoroughfare as much as a shrine.', array[]::text[], array[]::text[], 'Open all night and lit by lanterns after dark; walk through it on the way to or from Gion rather than making a trip of it.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['kyt-maruyama-park', 'kyt-gion']::text[], array[]::text[], array['yasaka-jinja.or.jp']::text[], 'draft'),
  ('kyt-gion', 'kyoto-city', 'Gion — Hanamikoji', '祇園 花見小路', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(135.775, 35.003), 4326)::extensions.geography, 'gion-shijo', 4, array['history', 'nightlife']::interest_tag[], 0.2, 0.85, 0.15, 0.7, null, 20, 45, 90, array['after 17:30']::text[], 'Tour groups fill Hanamikoji by day. Dusk is when it looks like the photographs, and when geiko actually walk to appointments.', array[]::text[], array[]::text[], 'Photographing geiko on private lanes is now fined — stay on Hanamikoji itself and keep the camera down when one passes. Shirakawa, two streets north, is prettier and quieter.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['kyt-yasaka-shrine', 'kyt-pontocho']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-maruyama-park', 'kyoto-city', 'Maruyama Park', '円山公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7815, 35.0035), 4326)::extensions.geography, 'gion-shijo', 8, array['nature']::interest_tag[], 0.15, 0.4, 0.3, 0.4, null, 15, 30, 60, array[]::text[], 'Quiet outside cherry-blossom season, when the weeping cherry draws the whole city at night.', array[]::text[], array[]::text[], 'The path from here up to Chion-in and Shoren-in is the calm way north through Higashiyama.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['kyt-yasaka-shrine', 'kyt-chionin']::text[], array['sakura']::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-chionin', 'kyoto-city', 'Chion-in', '知恩院', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7825, 35.0055), 4326)::extensions.geography, 'higashiyama', 10, array['shrines', 'history']::interest_tag[], 0.4, 0.4, 0.4, 0.6, 0.4, 30, 60, 90, array[]::text[], 'Rarely crowded — the scale of the place absorbs people.', array[]::text[], array['limited_mobility']::text[], 'The Sanmon gate is the largest wooden gate in Japan and free to stand under. The steep stairs behind it are the reason to come.', 500, 'none', null, '09:00', '16:30', false, array[]::int[], array[]::text[], array['kyt-maruyama-park', 'kyt-shorenin']::text[], array[]::text[], array['chion-in.or.jp']::text[], 'draft'),
  ('kyt-shorenin', 'kyoto-city', 'Shoren-in', '青蓮院', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.783, 35.0075), 4326)::extensions.geography, 'higashiyama', 6, array['shrines', 'nature']::interest_tag[], 0.2, 0.2, 0.65, 0.5, null, 30, 45, 60, array[]::text[], 'Nearly empty most days. Sit on the veranda and nobody hurries you.', array[]::text[], array[]::text[], 'Two minutes from Chion-in and a fraction of the visitors. The camphor trees outside are older than the temple.', 600, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['kyt-chionin']::text[], array['koyo']::text[], array['shorenin.com']::text[], 'draft'),
  ('kyt-heian-shrine', 'kyoto-city', 'Heian Shrine', '平安神宮', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7823, 35.0161), 4326)::extensions.geography, 'higashiyama', 10, array['shrines', 'nature']::interest_tag[], 0.2, 0.5, 0.3, 0.5, null, 20, 50, 80, array[]::text[], 'The courtyard is wide enough never to feel full. The garden behind it is where the time goes.', array[]::text[], array[]::text[], 'The shrine is free; the garden costs and is the better half — weeping cherries in April, a pond you cross on stepping stones.', 600, 'none', null, '08:30', '17:00', true, array[]::int[], array[]::text[], array[]::text[], array['sakura']::text[], array['heianjingu.or.jp']::text[], 'draft'),
  ('kyt-nanzenji', 'kyoto-city', 'Nanzen-ji', '南禅寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7935, 35.0113), 4326)::extensions.geography, 'keage', 8, array['shrines', 'history']::interest_tag[], 0.3, 0.5, 0.3, 0.7, null, 30, 60, 100, array[]::text[], 'The grounds are free and roomy. The Hojo garden and the gate top are ticketed and calmer.', array[]::text[], array[]::text[], 'The brick aqueduct in the grounds looks like it wandered in from Rome. Follow it uphill for five minutes to Nanzen-in, which almost nobody does.', 600, 'none', null, '08:40', '16:30', true, array[]::int[], array[]::text[], array['kyt-eikando', 'kyt-philosophers-path']::text[], array['koyo']::text[], array['nanzenji.or.jp']::text[], 'draft'),
  ('kyt-eikando', 'kyoto-city', 'Eikan-do', '永観堂', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7945, 35.0148), 4326)::extensions.geography, 'keage', 15, array['shrines', 'nature']::interest_tag[], 0.35, 0.6, 0.4, 0.6, null, 30, 60, 90, array[]::text[], 'Quiet most of the year; in the last three weeks of November it is the most visited maple temple in Kyoto and the price doubles.', array[]::text[], array[]::text[], 'Come for the maples or not at all — it is the reason the temple is famous. The Amida statue looking back over its shoulder is the other.', 600, 'none', null, '09:00', '17:00', true, array[]::int[], array[]::text[], array['kyt-nanzenji']::text[], array['koyo']::text[], array['eikando.or.jp']::text[], 'draft'),
  ('kyt-philosophers-path', 'kyoto-city', 'Philosopher''s Path', '哲学の道', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(135.795, 35.021), 4326)::extensions.geography, 'keage', 12, array['nature']::interest_tag[], 0.35, 0.5, 0.2, 0.6, null, 25, 45, 75, array[]::text[], 'A cherry-blossom week apart, it is a stroll not a crush. Cafés along it are the reason it takes longer than it looks.', array[]::text[], array[]::text[], 'Walk it north from Nanzen-ji to Ginkaku-ji so you finish at a temple, not a bus stop. Two kilometres, flat, canal-side.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['kyt-nanzenji', 'kyt-ginkakuji']::text[], array['sakura', 'koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-ginkakuji', 'kyoto-city', 'Ginkaku-ji', '銀閣寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7982, 35.027), 4326)::extensions.geography, 'ginkakuji-michi', 8, array['shrines', 'nature']::interest_tag[], 0.35, 0.6, 0.3, 0.7, null, 30, 60, 80, array[]::text[], 'A one-way path, so it moves. Mid-afternoon it slows to a shuffle at the sand garden.', array[]::text[], array[]::text[], 'Not silver, never was. The moss garden and the hill path above it are the reason it is better than Kinkaku-ji, whatever the postcards say.', 500, 'none', null, '09:00', '16:50', true, array[]::int[], array[]::text[], array['kyt-philosophers-path', 'kyt-honen-in']::text[], array['koyo']::text[], array['shokoku-ji.jp']::text[], 'draft'),
  ('kyt-honen-in', 'kyoto-city', 'Honen-in', '法然院', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.797, 35.0235), 4326)::extensions.geography, 'ginkakuji-michi', 10, array['shrines', 'nature']::interest_tag[], 0.25, 0.1, 0.85, 0.4, null, 15, 30, 45, array[]::text[], 'Often nobody at all. A thatched gate, two raked sand mounds, moss.', array[]::text[], array[]::text[], 'Three minutes off the Philosopher''s Path and the calmest place on it. The grounds are free; the hall opens only a few weeks a year.', 0, 'none', null, '06:00', '16:00', false, array[]::int[], array[]::text[], array['kyt-ginkakuji']::text[], array['koyo']::text[], array['honen-in.jp']::text[], 'draft'),
  ('kyt-tofukuji', 'kyoto-city', 'Tofuku-ji', '東福寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7735, 34.9764), 4326)::extensions.geography, 'tofukuji', 10, array['shrines', 'nature']::interest_tag[], 0.3, 0.7, 0.3, 0.6, null, 30, 60, 90, array['before 09:30']::text[], 'Empty eleven months a year. In late November the Tsutenkyo bridge is shoulder to shoulder by ten and photography is banned on it.', array[]::text[], array[]::text[], 'One stop from Kyoto Station on the way to Fushimi Inari — do them together. The Hojo garden''s checkerboard moss is modern and better than it sounds.', 600, 'none', null, '09:00', '16:00', true, array[]::int[], array[]::text[], array['kyt-fushimi-inari']::text[], array['koyo']::text[], array['tofukuji.jp']::text[], 'draft'),
  ('kyt-sanjusangendo', 'kyoto-city', 'Sanjusangen-do', '三十三間堂', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7717, 34.9878), 4326)::extensions.geography, 'shichijo', 7, array['shrines', 'history', 'art']::interest_tag[], 0.1, 0.4, 0.3, 0.7, null, 30, 50, 70, array[]::text[], 'Steady but never packed — the hall is 120 metres long and people spread out.', array[]::text[], array[]::text[], '1,001 gilded statues in one hall and no photographs allowed, which is why people walk it faster than they expect. Indoors: a good rain day.', 600, 'none', null, '09:00', '16:00', true, array[]::int[], array[]::text[], array['kyt-national-museum']::text[], array[]::text[], array['sanjusangendo.jp']::text[], 'draft'),
  ('kyt-national-museum', 'kyoto-city', 'Kyoto National Museum', '京都国立博物館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(135.773, 34.99), 4326)::extensions.geography, 'shichijo', 7, array['art', 'history']::interest_tag[], 0.1, 0.3, 0.4, 0.4, null, 45, 90, 150, array[]::text[], 'Quiet except during a headline special exhibition, when it is the busiest building in the city.', array[]::text[], array[]::text[], 'Closed Mondays, like most museums here. Across the road from Sanjusangen-do — pair them on a wet afternoon.', 700, 'none', null, '09:30', '17:00', true, array[1]::int[], array[]::text[], array['kyt-sanjusangendo']::text[], array[]::text[], array['kyohaku.go.jp']::text[], 'draft'),
  ('kyt-toji', 'kyoto-city', 'To-ji', '東寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7475, 34.9807), 4326)::extensions.geography, 'kyoto', 15, array['shrines', 'history']::interest_tag[], 0.2, 0.4, 0.4, 0.6, null, 25, 50, 80, array[]::text[], 'Calm, except on the 21st of each month when the flea market takes over the grounds.', array[]::text[], array[]::text[], 'The tallest wooden pagoda in Japan, fifteen minutes'' walk from the station — a good first or last thing in Kyoto. The 21st market is worth planning around.', 500, 'none', null, '08:00', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array['koyo']::text[], array['toji.or.jp']::text[], 'draft'),
  ('kyt-nishi-honganji', 'kyoto-city', 'Nishi Hongan-ji', '西本願寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7515, 34.9922), 4326)::extensions.geography, 'kyoto', 12, array['shrines', 'history']::interest_tag[], 0.15, 0.2, 0.6, 0.5, null, 20, 40, 60, array[]::text[], 'A working temple, so it is locals praying rather than visitors looking. Never full.', array[]::text[], array[]::text[], 'Free, vast, and ten minutes from the station. Take your shoes off and sit at the back of the main hall for ten minutes — that is the whole visit.', 0, 'none', null, '05:30', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['hongwanji.kyoto']::text[], 'draft'),
  ('kyt-nishiki-market', 'kyoto-city', 'Nishiki Market', '錦市場', 'market', extensions.ST_SetSRID(extensions.ST_MakePoint(135.764, 35.005), 4326)::extensions.geography, 'shijo', 5, array['food', 'shopping']::interest_tag[], 0.2, 0.85, 0.2, 0.6, null, 30, 60, 90, array['before 11:00']::text[], 'One narrow street, five blocks, and by noon you move at the pace of the slowest person in it.', array[]::text[], array[]::text[], 'Eat as you go; most stalls now ask you not to walk while eating, so step to the side. Many close by five and some are shut on Wednesdays.', 0, 'none', null, '10:00', '18:00', false, array[]::int[], array[]::text[], array['kyt-pontocho']::text[], array[]::text[], array['kyoto-nishiki.or.jp']::text[], 'draft'),
  ('kyt-pontocho', 'kyoto-city', 'Pontocho', '先斗町', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(135.771, 35.006), 4326)::extensions.geography, 'sanjo', 4, array['food', 'nightlife']::interest_tag[], 0.15, 0.7, 0.3, 0.6, null, 15, 45, 120, array['after 17:30']::text[], 'Dead by day. From dusk it is the prettiest lane in the city and every restaurant is full by eight.', array[]::text[], array[]::text[], 'An alley of restaurants along the river; in summer many have riverside decks. Book anything with a deck. For a drink without a booking, the bars at the north end.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['kyt-nishiki-market', 'kyt-gion']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-kamogawa', 'kyoto-city', 'Kamo River banks', '鴨川', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(135.772, 35.009), 4326)::extensions.geography, 'sanjo', 2, array['nature']::interest_tag[], 0.2, 0.3, 0.3, 0.5, null, 15, 30, 60, array[]::text[], 'Couples spaced out along the bank at even intervals, famously. Never crowded.', array[]::text[], array[]::text[], 'Free, always open, and the best place in Kyoto to do nothing. Buy something at a konbini and sit between Sanjo and Shijo at dusk.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['kyt-pontocho']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-nijo-castle', 'kyoto-city', 'Nijo Castle', '二条城', 'castle', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7481, 35.0142), 4326)::extensions.geography, 'nijojo-mae', 3, array['history']::interest_tag[], 0.3, 0.6, 0.2, 0.7, null, 45, 90, 120, array[]::text[], 'The Ninomaru palace is a one-way corridor and moves at the group in front. Mornings are noticeably better.', array[]::text[], array[]::text[], 'The nightingale floors squeak on purpose. Ninomaru is the point; the gardens are pleasant and the outer grounds can be skipped if time is short.', 1300, 'none', null, '08:45', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array['sakura']::text[], array['nijo-jocastle.city.kyoto.lg.jp']::text[], 'draft'),
  ('kyt-imperial-palace', 'kyoto-city', 'Kyoto Imperial Palace', '京都御所', 'palace', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7621, 35.0254), 4326)::extensions.geography, 'imadegawa', 8, array['history']::interest_tag[], 0.3, 0.3, 0.4, 0.5, null, 30, 60, 90, array[]::text[], 'Free entry since 2016 and still uncrowded — the park around it is enormous.', array[]::text[], array[]::text[], 'Closed Mondays. You see courtyards and façades, not interiors; the surrounding park is the better reason to come, especially with plum blossom in February.', 0, 'none', null, '09:00', '16:00', true, array[1]::int[], array[]::text[], array[]::text[], array[]::text[], array['sankan.kunaicho.go.jp']::text[], 'draft'),
  ('kyt-shimogamo', 'kyoto-city', 'Shimogamo Shrine', '下鴨神社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7727, 35.0393), 4326)::extensions.geography, 'demachiyanagi', 10, array['shrines', 'nature']::interest_tag[], 0.25, 0.3, 0.55, 0.5, null, 20, 45, 70, array[]::text[], 'Quiet. The approach through Tadasu forest is the quietest walk in central Kyoto.', array[]::text[], array[]::text[], 'Older than the city, and the forest around it is a scrap of what was here before Kyoto was. Combine with Demachiyanagi''s bakeries on the way.', 0, 'none', null, '06:30', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['shimogamo-jinja.or.jp']::text[], 'draft'),
  ('kyt-daitokuji', 'kyoto-city', 'Daitoku-ji', '大徳寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7462, 35.0437), 4326)::extensions.geography, 'kitaoji', 15, array['shrines', 'history']::interest_tag[], 0.3, 0.2, 0.7, 0.5, null, 30, 75, 120, array[]::text[], 'A walled town of sub-temples, most closed to the public, the open ones almost empty.', array[]::text[], array[]::text[], 'Daisen-in and Koto-in are the ones to pay for — dry gardens with nobody in them. This is the Kyoto that the tour buses miss entirely.', 500, 'none', null, '09:00', '16:30', false, array[]::int[], array[]::text[], array[]::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-kinkakuji', 'kyoto-city', 'Kinkaku-ji', '金閣寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7292, 35.0394), 4326)::extensions.geography, 'kinkakuji-michi', 5, array['shrines', 'history']::interest_tag[], 0.2, 0.9, 0.05, 0.85, null, 30, 45, 60, array['before 09:30']::text[], 'The most visited building in Kyoto. A one-way path past the pavilion, and by eleven it is a queue for the one photograph.', array[]::text[], array[]::text[], 'Go at opening. Forty-five minutes is plenty — the pavilion is the visit. The tea house near the exit is a fine place to let the crowd pass.', 500, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['kyt-ryoanji']::text[], array[]::text[], array['shokoku-ji.jp']::text[], 'draft'),
  ('kyt-ryoanji', 'kyoto-city', 'Ryoan-ji', '龍安寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7183, 35.0345), 4326)::extensions.geography, 'ryoanji-mae', 3, array['shrines', 'art']::interest_tag[], 0.2, 0.6, 0.3, 0.7, null, 20, 45, 70, array[]::text[], 'The rock garden veranda fills with people trying to see all fifteen stones. Early or late it is what it is meant to be.', array[]::text[], array[]::text[], 'Fifteen stones, and from any seat you can see fourteen — that is the design. Ten minutes on foot or one bus stop from Kinkaku-ji; do them together.', 600, 'none', null, '08:30', '16:30', true, array[]::int[], array[]::text[], array['kyt-kinkakuji', 'kyt-ninnaji']::text[], array[]::text[], array['ryoanji.jp']::text[], 'draft'),
  ('kyt-ninnaji', 'kyoto-city', 'Ninna-ji', '仁和寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.714, 35.031), 4326)::extensions.geography, 'ryoanji-mae', 12, array['shrines', 'history']::interest_tag[], 0.3, 0.3, 0.55, 0.5, null, 30, 60, 90, array[]::text[], 'Wide grounds, few people — except for its late-blooming cherries in mid-April, which draw the city.', array[]::text[], array[]::text[], 'Third in the Kinkaku-ji, Ryoan-ji line and the one most people drop. Keep it if you want a temple with room to breathe; drop it if the day is tight.', 800, 'none', null, '09:00', '16:30', true, array[]::int[], array[]::text[], array['kyt-ryoanji']::text[], array['sakura']::text[], array['ninnaji.jp']::text[], 'draft'),
  ('kyt-arashiyama-bamboo', 'kyoto-city', 'Arashiyama Bamboo Grove', '嵐山 竹林の小径', 'nature', extensions.ST_SetSRID(extensions.ST_MakePoint(135.6717, 35.017), 4326)::extensions.geography, 'saga-arashiyama', 12, array['nature']::interest_tag[], 0.35, 0.9, 0.1, 0.8, null, 20, 45, 90, array['before 08:00']::text[], 'A 300-metre path. After nine it is a slow procession with rickshaws pushing through; at seven it is silent and green.', array[]::text[], array[]::text[], 'It is shorter than you think. Come at dawn, then Tenryu-ji opens at 8:30 next door. The whole of Arashiyama is a half-day, and it is on the opposite side of the city from Fushimi Inari.', 0, 'none', null, null, null, false, array[]::int[], array['kyt-fushimi-inari']::text[], array['kyt-tenryuji', 'kyt-togetsukyo']::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-tenryuji', 'kyoto-city', 'Tenryu-ji', '天龍寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.6738, 35.0157), 4326)::extensions.geography, 'saga-arashiyama', 12, array['shrines', 'nature']::interest_tag[], 0.25, 0.7, 0.2, 0.7, null, 30, 60, 90, array[]::text[], 'Busy by mid-morning because it shares an exit with the bamboo grove. The garden is big enough to absorb it.', array[]::text[], array[]::text[], 'The garden is from 1339 and is the thing; you can skip the buildings. Its north gate opens straight into the bamboo grove.', 500, 'none', null, '08:30', '17:00', false, array[]::int[], array[]::text[], array['kyt-arashiyama-bamboo']::text[], array['koyo']::text[], array['tenryuji.com']::text[], 'draft'),
  ('kyt-togetsukyo', 'kyoto-city', 'Togetsukyo Bridge', '渡月橋', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.6775, 35.0125), 4326)::extensions.geography, 'saga-arashiyama', 18, array['nature']::interest_tag[], 0.15, 0.7, 0.1, 0.6, null, 10, 25, 45, array[]::text[], 'The bridge and its approach are the busiest part of Arashiyama all day.', array[]::text[], array[]::text[], 'The view of the hills from the bridge is the postcard; the river bank on the far side is where to sit with it. In autumn the hillside behind is the point.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['kyt-arashiyama-bamboo', 'kyt-monkey-park']::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-okochi-sanso', 'kyoto-city', 'Okochi Sanso Villa', '大河内山荘', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(135.669, 35.018), 4326)::extensions.geography, 'saga-arashiyama', 18, array['nature', 'history']::interest_tag[], 0.4, 0.2, 0.75, 0.5, 0.4, 30, 60, 75, array[]::text[], 'Almost empty, because it costs and it is at the top of the bamboo path where most people turn round.', array[]::text[], array['limited_mobility']::text[], 'A film star''s hillside garden with the best view over Kyoto in Arashiyama. The ticket includes tea and a sweet — sit down for it.', 1000, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['kyt-arashiyama-bamboo']::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-monkey-park', 'kyoto-city', 'Iwatayama Monkey Park', '嵐山モンキーパーク', 'nature', extensions.ST_SetSRID(extensions.ST_MakePoint(135.677, 35.0095), 4326)::extensions.geography, 'saga-arashiyama', 25, array['nature']::interest_tag[], 0.7, 0.5, 0.3, 0.5, 0.7, 45, 75, 100, array[]::text[], 'A steady stream of families. Never a queue, but the summit hut can be full of people feeding monkeys.', array[]::text[], array['limited_mobility']::text[], 'A twenty-minute uphill walk to reach the monkeys — genuinely steep. The view over the city from the top is the reward for people who came for the monkeys and got bored.', 800, 'none', null, '09:00', '16:00', true, array[]::int[], array[]::text[], array['kyt-togetsukyo']::text[], array[]::text[], array['monkeypark.jp']::text[], 'draft'),
  ('kyt-sagano-train', 'kyoto-city', 'Sagano Romantic Train', '嵯峨野トロッコ列車', 'nature', extensions.ST_SetSRID(extensions.ST_MakePoint(135.679, 35.018), 4326)::extensions.geography, 'saga-arashiyama', 5, array['nature']::interest_tag[], 0.1, 0.7, 0.3, 0.5, null, 30, 60, 120, array[]::text[], 'Sells out weeks ahead in November. Off-season you can walk up and buy a ticket.', array[]::text[], array[]::text[], 'Twenty-five minutes along the gorge in an open carriage. Sit on the right heading out. Closed Wednesdays and all winter — check before you plan around it.', 880, 'recommended', 30, null, null, false, array[3]::int[], array[]::text[], array[]::text[], array['koyo', 'sakura']::text[], array['sagano-kanko.co.jp']::text[], 'draft'),
  ('kyt-kennin-ji', 'kyoto-city', 'Kennin-ji', '建仁寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7736, 35.0004), 4326)::extensions.geography, 'gion-shijo', 6, array['shrines', 'art']::interest_tag[], 0.2, 0.3, 0.6, 0.5, null, 25, 45, 60, array[]::text[], 'Behind Gion and remarkably quiet given where it is.', array[]::text[], array[]::text[], 'The twin dragons painted across the ceiling of the Dharma hall are the reason to come. Kyoto''s oldest Zen temple, and you can sit on the veranda as long as you like.', 800, 'none', null, '10:00', '17:00', false, array[]::int[], array[]::text[], array['kyt-gion']::text[], array[]::text[], array['kenninji.jp']::text[], 'draft'),
  ('kyt-fushimi-sake', 'kyoto-city', 'Fushimi sake district', '伏見 酒蔵', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(135.762, 34.933), 4326)::extensions.geography, null, null, array['food', 'history']::interest_tag[], 0.25, 0.3, 0.65, 0.5, null, 45, 90, 150, array[]::text[], 'Quiet canals, white-walled breweries, and a tasting room that fills only on weekend afternoons.', array[]::text[], array[]::text[], 'The Gekkeikan Okura museum ticket comes with a tasting. Twenty minutes south of Fushimi Inari by Keihan — a natural afternoon after the shrine at dawn.', 600, 'none', null, '09:30', '16:30', false, array[]::int[], array[]::text[], array['kyt-fushimi-inari']::text[], array[]::text[], array['gekkeikan.co.jp']::text[], 'draft'),
  ('kyt-kurama-kibune', 'kyoto-city', 'Kurama to Kibune trail', '鞍馬・貴船', 'hike', extensions.ST_SetSRID(extensions.ST_MakePoint(135.771, 35.117), 4326)::extensions.geography, null, null, array['nature', 'shrines']::interest_tag[], 0.8, 0.4, 0.6, 0.6, 0.8, 120, 180, 300, array[]::text[], 'Busy on autumn weekends; quiet on weekdays.', array[]::text[], array['limited_mobility']::text[], 'A proper mountain walk between two temples, about two hours with the climb. Kibune''s riverside restaurants are the reward. Half a day including the train from Demachiyanagi.', 500, 'none', null, '09:00', '16:30', false, array[]::int[], array[]::text[], array[]::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('kyt-railway-museum', 'kyoto-city', 'Kyoto Railway Museum', '京都鉄道博物館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(135.742, 34.987), 4326)::extensions.geography, 'kyoto', 20, array['popculture', 'history']::interest_tag[], 0.2, 0.5, 0.4, 0.4, null, 60, 120, 180, array[]::text[], 'Families at weekends and in school holidays; calm on weekdays.', array[]::text[], array[]::text[], 'Closed Wednesdays. Fifty-odd real locomotives, a working turntable, and a rooftop deck where the actual Shinkansen passes below. The best rainy-day option with children in Kyoto.', 1500, 'none', null, '10:00', '17:00', false, array[3]::int[], array[]::text[], array[]::text[], array[]::text[], array['kyotorailwaymuseum.jp']::text[], 'draft'),
  ('kyt-kyoto-tower', 'kyoto-city', 'Kyoto Tower', '京都タワー', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7593, 34.9875), 4326)::extensions.geography, 'kyoto', 3, array['popculture']::interest_tag[], 0.1, 0.5, 0.05, 0.3, null, 20, 30, 45, array[]::text[], 'Never a long wait; never especially memorable.', array[]::text[], array[]::text[], 'Famous but thin: a view of a low city from a modest height. If you want the view of Kyoto, walk up Kiyomizu-dera. If you are killing an hour by the station in the rain, fine.', 900, 'none', null, '10:00', '21:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['kyoto-tower.jp']::text[], 'draft')
insert into places (id, city_id, name, name_ja, category, coords, nearest_station, station_walk_min, interest_tags, energy, crowd_level, discovery, signature, physical_demand, duration_taste_min, duration_typical_min, duration_full_min, best_window, crowd_note, worth_it_if, skip_if, local_tip, cost_jpy, booking_req, booking_lead_days, opens_at, closes_at, hours_vary, closed_weekdays, conflicts_with, pairs_with, seasons, sources, verification_status) values
  ('osk-osaka-castle', 'osaka-city', 'Osaka Castle', '大阪城', 'castle', extensions.ST_SetSRID(extensions.ST_MakePoint(135.5262, 34.6873), 4326)::extensions.geography, 'osakajokoen', 15, array['history']::interest_tag[], 0.35, 0.75, 0.1, 0.8, 0.4, 45, 90, 150, array['before 09:30']::text[], 'The keep is a museum with a lift queue. Weekend afternoons the wait for the lift is longer than the visit.', array[]::text[], array[]::text[], 'The keep is a 1931 concrete reconstruction with a museum inside; the view from the top and the walls and moats outside are the real castle. Walk the outer wall before going in.', 600, 'none', null, '09:00', '18:00', false, array[]::int[], array[]::text[], array['osk-castle-park']::text[], array['sakura']::text[], array['osakacastle.net']::text[], 'draft'),
  ('osk-castle-park', 'osaka-city', 'Osaka Castle Park', '大阪城公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(135.53, 34.69), 4326)::extensions.geography, 'osakajokoen', 5, array['nature']::interest_tag[], 0.3, 0.4, 0.2, 0.4, null, 20, 45, 90, array[]::text[], 'Roomy, except in the first week of April when the plum and cherry groves draw the city.', array[]::text[], array[]::text[], 'The Nishinomaru garden costs a little and has the classic view of the keep across the moat. Runners and dog walkers at dawn; a good jet-lag morning.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['osk-osaka-castle']::text[], array['sakura']::text[], array['osakacastlepark.jp']::text[], 'draft'),
  ('osk-dotonbori', 'osaka-city', 'Dotonbori', '道頓堀', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(135.5013, 34.6687), 4326)::extensions.geography, 'namba', 5, array['food', 'nightlife', 'popculture']::interest_tag[], 0.2, 0.95, 0.05, 0.9, null, 30, 75, 150, array['after 17:30']::text[], 'Packed every evening of the year. That is the point; go when it is loud.', array[]::text[], array[]::text[], 'The Glico running man is on the bridge; everyone photographs it and moves on. The food is why you are here — takoyaki, kushikatsu, okonomiyaki — and the side streets are better than the canal front.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['osk-hozenji', 'osk-kuromon']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-hozenji', 'osaka-city', 'Hozenji Yokocho', '法善寺横丁', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(135.503, 34.6675), 4326)::extensions.geography, 'namba', 6, array['food', 'history']::interest_tag[], 0.1, 0.5, 0.55, 0.5, null, 10, 30, 60, array['after 17:30']::text[], 'Two lantern-lit lanes a minute from Dotonbori and a different century. Never crowded — most people walk past the entrance.', array[]::text[], array[]::text[], 'Throw water on the moss-covered Fudo statue at the tiny temple; that is the ritual. Then eat at any of the counters — it is the calm alternative to the canal.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['osk-dotonbori']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-kuromon', 'osaka-city', 'Kuromon Market', '黒門市場', 'market', extensions.ST_SetSRID(extensions.ST_MakePoint(135.506, 34.664), 4326)::extensions.geography, 'nippombashi', 3, array['food']::interest_tag[], 0.2, 0.8, 0.2, 0.6, null, 30, 60, 90, array['before 11:00']::text[], 'Tourist-heavy by late morning and priced accordingly. Early it is still a market.', array[]::text[], array[]::text[], 'Grilled seafood eaten standing up. Prices have climbed with the crowds; it is worth it once, for the scallops and the atmosphere, not for a cheap lunch.', 0, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['osk-dotonbori']::text[], array[]::text[], array['kuromon.com']::text[], 'draft'),
  ('osk-shinsekai', 'osaka-city', 'Shinsekai', '新世界', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(135.5063, 34.6525), 4326)::extensions.geography, 'dobutsuen-mae', 5, array['food', 'nightlife', 'history']::interest_tag[], 0.2, 0.6, 0.4, 0.6, null, 30, 60, 120, array['after 17:30']::text[], 'Lively in the evening, a little forlorn by day. Weekends are its natural state.', array[]::text[], array[]::text[], 'Retro Osaka — kushikatsu (skewers) is the dish, and the rule is no double-dipping in the sauce. Rougher-edged than Dotonbori and better for it.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['osk-tsutenkaku', 'osk-spa-world']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-tsutenkaku', 'osaka-city', 'Tsutenkaku Tower', '通天閣', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.5063, 34.6525), 4326)::extensions.geography, 'dobutsuen-mae', 7, array['popculture']::interest_tag[], 0.1, 0.5, 0.2, 0.4, null, 20, 40, 60, array[]::text[], 'Short waits; the observation deck is small.', array[]::text[], array[]::text[], 'Loved for what it is, not for the view. Rub the Billiken statue''s feet for luck and come back down — the neighbourhood around it is the attraction.', 1500, 'none', null, '09:00', '21:45', false, array[]::int[], array[]::text[], array['osk-shinsekai']::text[], array[]::text[], array['tsutenkaku.co.jp']::text[], 'draft'),
  ('osk-spa-world', 'osaka-city', 'Spa World', 'スパワールド', 'onsen', extensions.ST_SetSRID(extensions.ST_MakePoint(135.505, 34.651), 4326)::extensions.geography, 'dobutsuen-mae', 5, array['onsen']::interest_tag[], 0.1, 0.5, 0.3, 0.4, null, 60, 120, 240, array[]::text[], 'Busy on weekend evenings. Weekday afternoons you can have a themed bath to yourself.', array[]::text[], array[]::text[], 'A vast bath complex with ''European'' and ''Asian'' floors that swap between men and women monthly. Tattoos are not allowed. A good way to spend a rainy afternoon in the south of the city.', 1500, 'none', null, '10:00', '23:59', false, array[]::int[], array[]::text[], array['osk-shinsekai']::text[], array[]::text[], array['spaworld.co.jp']::text[], 'draft'),
  ('osk-shitennoji', 'osaka-city', 'Shitenno-ji', '四天王寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.5164, 34.6537), 4326)::extensions.geography, 'tennoji', 10, array['shrines', 'history']::interest_tag[], 0.25, 0.3, 0.5, 0.5, null, 30, 60, 90, array[]::text[], 'Quiet except on the 21st and 22nd of each month, when the flea market fills the grounds.', array[]::text[], array[]::text[], 'Japan''s oldest official temple, founded 593 — and rebuilt in concrete after the war, so it is the layout and the ritual that are old. The garden is the calm part.', 500, 'none', null, '08:30', '16:00', true, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['shitennoji.or.jp']::text[], 'draft'),
  ('osk-abeno-harukas', 'osaka-city', 'Abeno Harukas 300', 'あべのハルカス', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.5137, 34.6459), 4326)::extensions.geography, 'tennoji', 3, array['popculture']::interest_tag[], 0.1, 0.6, 0.1, 0.6, null, 30, 45, 75, array['after 17:30']::text[], 'Sunset slots are busiest; late evening is calm and the view is better anyway.', array[]::text[], array[]::text[], 'Japan''s tallest building until recently, with a 360° deck on floors 58–60. Go after dark. The 16th-floor garden terrace is free and good enough for many people.', 2000, 'none', null, '09:00', '22:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['abenoharukas-300.jp']::text[], 'draft'),
  ('osk-tennoji-park', 'osaka-city', 'Tennoji Park & Keitakuen', '天王寺公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(135.51, 34.651), 4326)::extensions.geography, 'tennoji', 5, array['nature']::interest_tag[], 0.2, 0.4, 0.4, 0.3, null, 15, 40, 75, array[]::text[], 'Families on the lawn; the Keitakuen garden inside is nearly empty.', array[]::text[], array[]::text[], 'The lawn is a good place to sit; Keitakuen is a small formal garden that costs almost nothing and has nobody in it. The zoo is fine for children, skippable otherwise.', 150, 'none', null, '09:30', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-umeda-sky', 'osaka-city', 'Umeda Sky Building', '梅田スカイビル', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.49, 34.7053), 4326)::extensions.geography, 'osaka', 10, array['popculture']::interest_tag[], 0.1, 0.6, 0.2, 0.6, null, 30, 45, 75, array['after 17:30']::text[], 'Sunset draws a queue for the escalator; an hour after dark it moves freely.', array[]::text[], array[]::text[], 'The open-air ring at the top is what makes it — wind in your hair, the city all round. The escalator between the two towers, in a glass tube, is half the fun.', 2000, 'none', null, '09:30', '22:30', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['skybldg.co.jp']::text[], 'draft'),
  ('osk-kaiyukan', 'osaka-city', 'Osaka Aquarium Kaiyukan', '海遊館', 'aquarium', extensions.ST_SetSRID(extensions.ST_MakePoint(135.429, 34.6545), 4326)::extensions.geography, 'osakako', 5, array['nature', 'popculture']::interest_tag[], 0.2, 0.8, 0.1, 0.6, null, 60, 120, 180, array[]::text[], 'Very busy at weekends and in holidays. Weekday late afternoons are the calm window.', array[]::text[], array[]::text[], 'One of the best aquariums in the world, built as a spiral around a whale shark tank. Buy a timed ticket online to skip the queue. Forty minutes from the centre — it is a half-day with the ferris wheel next door.', 2700, 'recommended', 7, '10:00', '20:00', false, array[]::int[], array[]::text[], array['osk-tempozan-wheel']::text[], array[]::text[], array['kaiyukan.com']::text[], 'draft'),
  ('osk-tempozan-wheel', 'osaka-city', 'Tempozan Ferris Wheel', '天保山大観覧車', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.4315, 34.656), 4326)::extensions.geography, 'osakako', 5, array['popculture']::interest_tag[], 0.05, 0.4, 0.2, 0.3, null, 15, 25, 35, array[]::text[], 'Short waits outside holidays.', array[]::text[], array[]::text[], 'Fifteen minutes round. Next to the aquarium — worth it only if you are already there, and best after dark when the port is lit.', 900, 'none', null, '10:00', '21:00', false, array[]::int[], array[]::text[], array['osk-kaiyukan']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-sumiyoshi-taisha', 'osaka-city', 'Sumiyoshi Taisha', '住吉大社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(135.493, 34.6125), 4326)::extensions.geography, null, null, array['shrines', 'history']::interest_tag[], 0.2, 0.3, 0.6, 0.6, null, 30, 50, 80, array[]::text[], 'Quiet on ordinary days; enormous at New Year.', array[]::text[], array[]::text[], 'A shrine style older than Buddhism''s arrival, with the steeply arched red bridge everyone photographs. Twenty minutes south of Namba on the Nankai line, then a two-minute walk from Sumiyoshi-taisha station.', 0, 'none', null, '06:30', '17:00', true, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['sumiyoshitaisha.net']::text[], 'draft'),
  ('osk-museum-of-history', 'osaka-city', 'Osaka Museum of History', '大阪歴史博物館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(135.52, 34.683), 4326)::extensions.geography, 'tanimachi-4chome', 2, array['history']::interest_tag[], 0.15, 0.3, 0.5, 0.5, null, 45, 90, 120, array[]::text[], 'Quiet. School groups on weekday mornings.', array[]::text[], array[]::text[], 'Closed Tuesdays. Start on the top floor — the reconstructed Naniwa palace hall — and work down through the centuries. The window view of Osaka Castle from up there is the best free castle photograph in the city.', 600, 'none', null, '09:30', '17:00', false, array[2]::int[], array[]::text[], array['osk-osaka-castle']::text[], array[]::text[], array['osakamushis.jp']::text[], 'draft'),
  ('osk-nakanoshima-park', 'osaka-city', 'Nakanoshima Park', '中之島公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(135.51, 34.6925), 4326)::extensions.geography, 'osaka', 15, array['nature']::interest_tag[], 0.2, 0.3, 0.5, 0.4, null, 20, 40, 75, array[]::text[], 'Office workers at lunch, otherwise sparse. The rose garden draws people in May and October.', array[]::text[], array[]::text[], 'A long thin island between two rivers, with a rose garden at the east end and the red-brick Central Public Hall. The calm centre of a loud city.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['osk-nakanoshima-museum']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-nakanoshima-museum', 'osaka-city', 'Nakanoshima Museum of Art', '大阪中之島美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(135.49, 34.691), 4326)::extensions.geography, 'osaka', 15, array['art']::interest_tag[], 0.15, 0.4, 0.4, 0.5, null, 45, 90, 150, array[]::text[], 'Depends entirely on the exhibition. The permanent collection floors are calm.', array[]::text[], array[]::text[], 'Closed Mondays. Opened 2022, a black cube with Modigliani and Dalí in the permanent collection and strong design shows. The National Museum of Art is next door — one ticket each, plan both.', 1500, 'none', null, '10:00', '17:00', false, array[1]::int[], array[]::text[], array['osk-national-museum-art']::text[], array[]::text[], array['nakka-art.jp']::text[], 'draft'),
  ('osk-national-museum-art', 'osaka-city', 'National Museum of Art, Osaka', '国立国際美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(135.4915, 34.6915), 4326)::extensions.geography, 'osaka', 18, array['art']::interest_tag[], 0.15, 0.3, 0.5, 0.4, null, 45, 75, 120, array[]::text[], 'Quiet unless a headline show is on.', array[]::text[], array[]::text[], 'Closed Mondays. Entirely underground, beneath a steel sculpture that looks like bamboo. Contemporary and postwar Japanese art, cheaply.', 430, 'none', null, '10:00', '17:00', false, array[1]::int[], array[]::text[], array['osk-nakanoshima-museum']::text[], array[]::text[], array['nmao.go.jp']::text[], 'draft'),
  ('osk-shinsaibashi-suji', 'osaka-city', 'Shinsaibashi-suji', '心斎橋筋商店街', 'shopping', extensions.ST_SetSRID(extensions.ST_MakePoint(135.5015, 34.674), 4326)::extensions.geography, 'shinsaibashi', 1, array['shopping']::interest_tag[], 0.2, 0.85, 0.1, 0.4, null, 30, 60, 150, array[]::text[], 'A covered street 600 metres long and always full. Weekend afternoons are a slow drift.', array[]::text[], array[]::text[], 'Everything from drugstores to department stores under one roof, ending at Dotonbori. Useful rather than special; the drugstores are where visitors actually spend.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['osk-amerikamura', 'osk-dotonbori']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-amerikamura', 'osaka-city', 'Amerikamura', 'アメリカ村', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(135.498, 34.6725), 4326)::extensions.geography, 'shinsaibashi', 5, array['shopping', 'popculture', 'nightlife']::interest_tag[], 0.2, 0.6, 0.4, 0.4, null, 20, 45, 90, array['after 17:30']::text[], 'Teenagers and vintage shoppers by afternoon; bars by night.', array[]::text[], array[]::text[], 'Osaka''s Harajuku, more or less — vintage clothes, street food, a small triangle park where everyone sits. Better in the evening.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['osk-shinsaibashi-suji']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-den-den-town', 'osaka-city', 'Den Den Town', 'でんでんタウン', 'shopping', extensions.ST_SetSRID(extensions.ST_MakePoint(135.506, 34.6615), 4326)::extensions.geography, 'nippombashi', 3, array['popculture', 'shopping']::interest_tag[], 0.2, 0.5, 0.4, 0.4, null, 30, 60, 150, array[]::text[], 'Busy at weekends, easy on weekdays.', array[]::text[], array[]::text[], 'Osaka''s Akihabara: anime, figures, retro games, electronics. Smaller and cheaper than Tokyo''s, and five minutes from Kuromon Market.', 0, 'none', null, '11:00', '20:00', false, array[]::int[], array[]::text[], array['osk-kuromon']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-namba-yasaka', 'osaka-city', 'Namba Yasaka Shrine', '難波八阪神社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(135.496, 34.662), 4326)::extensions.geography, 'namba', 8, array['shrines', 'popculture']::interest_tag[], 0.1, 0.4, 0.55, 0.5, null, 10, 20, 30, array[]::text[], 'A steady trickle for the photograph; rarely more.', array[]::text[], array[]::text[], 'A twelve-metre lion''s head with a stage inside its mouth. Ten minutes; the surprise is the visit. Free.', 0, 'none', null, '06:30', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-osaka-tenmangu', 'osaka-city', 'Osaka Tenmangu', '大阪天満宮', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(135.512, 34.696), 4326)::extensions.geography, null, null, array['shrines']::interest_tag[], 0.15, 0.3, 0.5, 0.4, null, 15, 30, 45, array[]::text[], 'Quiet outside the Tenjin festival in late July, which is one of Japan''s three biggest.', array[]::text[], array[]::text[], 'Dedicated to the god of learning, so students come before exams. Next to Tenjimbashisuji — Japan''s longest covered shopping street — which is the better reason to come this way.', 0, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['osk-tenjimbashisuji']::text[], array[]::text[], array['tenjinsan.com']::text[], 'draft'),
  ('osk-tenjimbashisuji', 'osaka-city', 'Tenjimbashisuji Shopping Street', '天神橋筋商店街', 'shopping', extensions.ST_SetSRID(extensions.ST_MakePoint(135.512, 34.705), 4326)::extensions.geography, null, null, array['shopping', 'food']::interest_tag[], 0.3, 0.5, 0.6, 0.4, null, 30, 60, 120, array[]::text[], 'Locals shopping, not tourists browsing. Comfortable all day.', array[]::text[], array[]::text[], '2.6 km under one roof — the longest in Japan — and the most ordinary-Osaka thing you can do. Cheap lunches, old shops, nobody selling you anything.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['osk-osaka-tenmangu']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-minoo-falls', 'osaka-city', 'Minoo Falls', '箕面大滝', 'nature', extensions.ST_SetSRID(extensions.ST_MakePoint(135.472, 34.853), 4326)::extensions.geography, null, null, array['nature']::interest_tag[], 0.55, 0.5, 0.6, 0.5, 0.5, 60, 120, 180, array[]::text[], 'Packed on November weekends for the maples; calm the rest of the year.', array[]::text[], array['limited_mobility']::text[], 'A flat, paved 3 km riverside walk to a 33-metre waterfall — a valley, not a hike. Thirty minutes from Umeda on the Hankyu line. The deep-fried maple leaves sold along the path are a real thing.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array[]::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('osk-expo-park', 'osaka-city', 'Expo ''70 Park & Tower of the Sun', '万博記念公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(135.533, 34.809), 4326)::extensions.geography, null, null, array['art', 'nature', 'popculture']::interest_tag[], 0.35, 0.4, 0.5, 0.5, null, 45, 120, 240, array[]::text[], 'Roomy — it is huge. The Tower interior has timed entry and sells out at weekends.', array[]::text[], array[]::text[], 'Closed Wednesdays. Taro Okamoto''s Tower of the Sun is the strangest great building in Japan and you can now go inside it — book ahead. Forty minutes from Umeda on the monorail.', 260, 'recommended', 14, '09:30', '17:00', false, array[3]::int[], array[]::text[], array[]::text[], array[]::text[], array['expo70-park.jp']::text[], 'draft'),
  ('osk-teamlab-botanical', 'osaka-city', 'teamLab Botanical Garden', 'チームラボ ボタニカルガーデン', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(135.519, 34.61), 4326)::extensions.geography, null, null, array['art', 'nature', 'popculture']::interest_tag[], 0.3, 0.7, 0.3, 0.6, null, 60, 90, 120, array['after 17:30']::text[], 'Timed entry keeps it moving, but weekend slots sell out a week or two ahead.', array[]::text[], array[]::text[], 'Light art across a real botanical garden in Nagai Park, after dark. Book a slot online; it is not a walk-up. Thirty minutes south of Namba on the Midosuji line.', 1800, 'required', 14, '19:45', '21:30', true, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['teamlab.art']::text[], 'draft')
insert into places (id, city_id, name, name_ja, category, coords, nearest_station, station_walk_min, interest_tags, energy, crowd_level, discovery, signature, physical_demand, duration_taste_min, duration_typical_min, duration_full_min, best_window, crowd_note, worth_it_if, skip_if, local_tip, cost_jpy, booking_req, booking_lead_days, opens_at, closes_at, hours_vary, closed_weekdays, conflicts_with, pairs_with, seasons, sources, verification_status) values
  ('nra-todaiji', 'nara-city', 'Todai-ji', '東大寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8398, 34.689), 4326)::extensions.geography, 'kintetsu-nara', 20, array['shrines', 'history']::interest_tag[], 0.3, 0.9, 0.05, 0.95, null, 30, 60, 100, array['before 09:00']::text[], 'School groups from mid-morning; the hall is big enough that it never quite feels full, but the approach does.', array[]::text[], array[]::text[], 'The largest bronze Buddha in Japan in one of the largest wooden buildings in the world. Come as it opens and you get the hall almost alone. The pillar with a hole in it is for children.', 800, 'none', null, '08:00', '17:00', true, array[]::int[], array[]::text[], array['nra-nara-park', 'nra-nigatsudo']::text[], array[]::text[], array['todaiji.or.jp']::text[], 'draft'),
  ('nra-nara-park', 'nara-city', 'Nara Park & the deer', '奈良公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(135.843, 34.6851), 4326)::extensions.geography, 'kintetsu-nara', 5, array['nature']::interest_tag[], 0.3, 0.7, 0.05, 0.8, null, 30, 60, 120, array[]::text[], 'The deer are everywhere and so are the people feeding them. It thins out the further you walk from the station.', array[]::text[], array[]::text[], 'Buy the crackers, hold them up, and the deer bow — then they push. Keep paper and maps out of reach; they eat those too. The park connects everything: Todai-ji, Kasuga, Kofuku-ji are all inside it.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['nra-todaiji', 'nra-kasuga-taisha', 'nra-kofukuji']::text[], array['koyo', 'sakura']::text[], array['wikivoyage']::text[], 'draft'),
  ('nra-kasuga-taisha', 'nara-city', 'Kasuga Taisha', '春日大社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8483, 34.6815), 4326)::extensions.geography, 'kintetsu-nara', 25, array['shrines', 'nature']::interest_tag[], 0.35, 0.5, 0.3, 0.8, null, 30, 60, 90, array[]::text[], 'The approach through the forest thins the crowd; the inner shrine is busy but moves.', array[]::text[], array[]::text[], 'Three thousand lanterns — stone ones lining the forest path, bronze ones hanging in the shrine. The dark room where they are all lit is the thing to pay for. The walk in from the park is part of it.', 500, 'none', null, '07:00', '17:00', true, array[]::int[], array[]::text[], array['nra-nara-park']::text[], array[]::text[], array['kasugataisha.or.jp']::text[], 'draft'),
  ('nra-kofukuji', 'nara-city', 'Kofuku-ji', '興福寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.832, 34.683), 4326)::extensions.geography, 'kintetsu-nara', 5, array['shrines', 'history', 'art']::interest_tag[], 0.2, 0.5, 0.3, 0.7, null, 20, 45, 75, array[]::text[], 'Grounds are open and roomy. The treasure hall has a short queue on weekends.', array[]::text[], array[]::text[], 'The five-storey pagoda is the symbol of Nara and free to walk around. Pay for the National Treasure Hall: the Ashura statue inside is the most famous sculpture in Japan for a reason.', 700, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['nra-nara-park', 'nra-sarusawa-pond']::text[], array[]::text[], array['kohfukuji.com']::text[], 'draft'),
  ('nra-isuien', 'nara-city', 'Isuien Garden', '依水園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8375, 34.688), 4326)::extensions.geography, 'kintetsu-nara', 15, array['nature']::interest_tag[], 0.15, 0.2, 0.7, 0.5, null, 30, 45, 70, array[]::text[], 'Nearly empty. A dozen people on a busy day.', array[]::text[], array[]::text[], 'Closed Tuesdays. Two gardens, one older than the other, with Todai-ji''s gate borrowed as scenery. Two minutes from Todai-ji and a fraction of the visitors. Tea in the pavilion is worth the wait.', 1200, 'none', null, '09:30', '16:30', false, array[2]::int[], array[]::text[], array['nra-todaiji', 'nra-yoshikien']::text[], array['koyo']::text[], array['isuien.or.jp']::text[], 'draft'),
  ('nra-yoshikien', 'nara-city', 'Yoshikien Garden', '吉城園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8365, 34.6875), 4326)::extensions.geography, 'kintetsu-nara', 15, array['nature']::interest_tag[], 0.15, 0.15, 0.75, 0.4, null, 20, 30, 45, array[]::text[], 'Empty. Genuinely.', array[]::text[], array[]::text[], 'Next door to Isuien, smaller, and free — the moss garden and the thatched tea house are the whole thing. Twenty minutes of quiet between two crowded temples.', 0, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['nra-isuien']::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('nra-naramachi', 'nara-city', 'Naramachi', 'ならまち', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(135.83, 34.678), 4326)::extensions.geography, 'kintetsu-nara', 12, array['history', 'shopping', 'food']::interest_tag[], 0.25, 0.3, 0.5, 0.5, null, 30, 60, 120, array[]::text[], 'Calm — most day-trippers never leave the park.', array[]::text[], array[]::text[], 'The old merchant quarter south of the park: lattice-fronted houses, small cafés, a free machiya you can walk through. The red cloth monkeys hanging outside doors are charms. A good late afternoon.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['nra-sarusawa-pond']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('nra-nigatsudo', 'nara-city', 'Nigatsu-do', '二月堂', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8445, 34.6905), 4326)::extensions.geography, 'kintetsu-nara', 30, array['shrines', 'nature']::interest_tag[], 0.4, 0.3, 0.55, 0.6, 0.4, 15, 30, 45, array[]::text[], 'A few people on the balcony at any time; empty at dusk, which is when to be there.', array[]::text[], array['limited_mobility']::text[], 'A hall on stilts up the hill behind Todai-ji, free and open all hours, with the best view over Nara. Sunset from the balcony is the best free thing in the city.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['nra-todaiji']::text[], array[]::text[], array['todaiji.or.jp']::text[], 'draft'),
  ('nra-national-museum', 'nara-city', 'Nara National Museum', '奈良国立博物館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(135.838, 34.684), 4326)::extensions.geography, 'kintetsu-nara', 12, array['art', 'history']::interest_tag[], 0.15, 0.3, 0.4, 0.5, null, 45, 90, 150, array[]::text[], 'Calm, except during the Shosoin exhibition each autumn, when the queue crosses the park.', array[]::text[], array[]::text[], 'Closed Mondays. The Buddhist sculpture hall is the finest single room of its kind in Japan — go for that alone. In the park, so it fits between Kofuku-ji and Todai-ji.', 700, 'none', null, '09:30', '17:00', false, array[1]::int[], array[]::text[], array[]::text[], array[]::text[], array['narahaku.go.jp']::text[], 'draft'),
  ('nra-horyuji', 'nara-city', 'Horyu-ji', '法隆寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7342, 34.6146), 4326)::extensions.geography, 'horyuji', 20, array['shrines', 'history']::interest_tag[], 0.35, 0.3, 0.5, 0.8, null, 45, 90, 150, array[]::text[], 'Never crowded — it is outside the city and most day-trippers do not get here.', array[]::text[], array[]::text[], 'The oldest wooden buildings in the world, from about 600 AD, and quiet. Twelve minutes by train from Nara then a walk or bus. A half-day; do it on the way to or from Osaka.', 1500, 'none', null, '08:00', '16:30', true, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['horyuji.or.jp']::text[], 'draft'),
  ('nra-toshodaiji', 'nara-city', 'Toshodai-ji', '唐招提寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7847, 34.6756), 4326)::extensions.geography, null, null, array['shrines', 'history']::interest_tag[], 0.3, 0.2, 0.65, 0.6, null, 30, 60, 90, array[]::text[], 'Quiet. Nishinokyo gets a fraction of the park''s visitors.', array[]::text[], array[]::text[], 'Founded by the blind Chinese monk Ganjin in 759, and the main hall is the great Nara-period building still standing. Five minutes'' walk from Yakushi-ji; do both from Nishinokyo station on the Kintetsu line.', 1000, 'none', null, '08:30', '17:00', false, array[]::int[], array[]::text[], array['nra-yakushiji']::text[], array[]::text[], array['toshodaiji.jp']::text[], 'draft'),
  ('nra-yakushiji', 'nara-city', 'Yakushi-ji', '薬師寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7845, 34.6685), 4326)::extensions.geography, null, null, array['shrines', 'history']::interest_tag[], 0.3, 0.2, 0.6, 0.6, null, 30, 60, 90, array[]::text[], 'Quiet.', array[]::text[], array[]::text[], 'Twin pagodas, one from 730 and one rebuilt in 1981 — stand between them and see the difference twelve centuries makes. Pair with Toshodai-ji next door.', 1000, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['nra-toshodaiji']::text[], array[]::text[], array['yakushiji.or.jp']::text[], 'draft'),
  ('nra-heijo-palace', 'nara-city', 'Heijo Palace site', '平城宮跡', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(135.795, 34.691), 4326)::extensions.geography, null, null, array['history', 'nature']::interest_tag[], 0.4, 0.15, 0.7, 0.4, 0.4, 30, 60, 120, array[]::text[], 'Empty fields with a few reconstructed gates; you may see nobody.', array[]::text[], array[]::text[], 'Where the capital was, 710–784, before Kyoto. Mostly grass, with the great gate and a hall rebuilt at full size. For people who like the idea of a place more than the place. Bring a bicycle.', 0, 'none', null, '09:00', '16:30', false, array[1]::int[], array[]::text[], array[]::text[], array[]::text[], array['heijo-park.jp']::text[], 'draft'),
  ('nra-wakakusa', 'nara-city', 'Mount Wakakusa', '若草山', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.856, 34.687), 4326)::extensions.geography, 'kintetsu-nara', 35, array['nature']::interest_tag[], 0.55, 0.3, 0.5, 0.5, 0.6, 30, 60, 90, array[]::text[], 'A few walkers and a lot of deer.', array[]::text[], array['limited_mobility']::text[], 'A grass hill behind the park; twenty minutes of steps to the first summit and a view over the whole plain. Closed in winter, and burned deliberately each January in a festival. Deer follow you up.', 150, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['nra-nara-park']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('nra-kasugayama-forest', 'nara-city', 'Kasugayama Primeval Forest', '春日山原始林', 'hike', extensions.ST_SetSRID(extensions.ST_MakePoint(135.862, 34.683), 4326)::extensions.geography, null, null, array['nature']::interest_tag[], 0.8, 0.1, 0.8, 0.4, 0.8, 90, 150, 240, array[]::text[], 'You will meet more deer than people.', array[]::text[], array['limited_mobility']::text[], 'A forest untouched since 841, when hunting and logging were banned. A 10 km loop on forest roads behind Kasuga Taisha. A real half-day walk; not for a tight schedule.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array[]::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('nra-nakatanidou', 'nara-city', 'Nakatanidou mochi', '中谷堂', 'food', extensions.ST_SetSRID(extensions.ST_MakePoint(135.829, 34.6815), 4326)::extensions.geography, 'kintetsu-nara', 3, array['food']::interest_tag[], 0.05, 0.6, 0.3, 0.5, null, 10, 15, 25, array[]::text[], 'A crowd gathers whenever the pounding starts, which is every half hour or so.', array[]::text[], array[]::text[], 'The fastest mochi-pounders in Japan, hammering rice at a rate that looks dangerous. Watch, then buy one warm for a few hundred yen. Ten minutes and worth every one.', 0, 'none', null, '10:00', '19:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['nakatanidou.jp']::text[], 'draft'),
  ('nra-sarusawa-pond', 'nara-city', 'Sarusawa Pond', '猿沢池', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.831, 34.681), 4326)::extensions.geography, 'kintetsu-nara', 5, array['nature']::interest_tag[], 0.05, 0.3, 0.4, 0.3, null, 10, 15, 30, array[]::text[], 'Never busy.', array[]::text[], array[]::text[], 'The pagoda of Kofuku-ji reflected in a pond with willows and turtles — the classic Nara view, free, five minutes from the station. Best at dusk.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['nra-kofukuji', 'nra-naramachi']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('nra-gangoji', 'nara-city', 'Gango-ji', '元興寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8305, 34.6775), 4326)::extensions.geography, 'kintetsu-nara', 12, array['shrines', 'history']::interest_tag[], 0.15, 0.2, 0.65, 0.5, null, 20, 40, 60, array[]::text[], 'Quiet — it sits inside Naramachi and most people walk past the gate.', array[]::text[], array[]::text[], 'World Heritage and almost unvisited. Some of the roof tiles are from the 6th century, moved here from Japan''s first temple at Asuka; look for the darker, rougher ones. Twenty minutes is enough.', 500, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['nra-naramachi']::text[], array[]::text[], array['gangoji-tera.or.jp']::text[], 'draft'),
  ('nra-shin-yakushiji', 'nara-city', 'Shin-Yakushi-ji', '新薬師寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8455, 34.6765), 4326)::extensions.geography, null, null, array['shrines', 'art']::interest_tag[], 0.2, 0.1, 0.85, 0.5, null, 20, 40, 60, array[]::text[], 'A handful of people in the hall at any time.', array[]::text[], array[]::text[], 'One hall, one 8th-century Buddha, and the Twelve Heavenly Generals ringed around it in clay — the finest set in Japan and you stand a metre from them. Twenty minutes'' walk south-east of the park through the Takabatake lanes.', 600, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['shinyakushiji.or.jp']::text[], 'draft'),
  ('nra-todaiji-museum', 'nara-city', 'Todai-ji Museum', '東大寺ミュージアム', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8385, 34.6875), 4326)::extensions.geography, 'kintetsu-nara', 18, array['art', 'history']::interest_tag[], 0.1, 0.3, 0.5, 0.4, null, 30, 45, 75, array[]::text[], 'Calm even when the Great Buddha Hall outside is heaving.', array[]::text[], array[]::text[], 'The statues that used to live in the temple''s older halls, lit properly for once — the Nikko and Gakko bodhisattvas are the reason. The combined ticket with the Great Buddha Hall saves a few hundred yen.', 600, 'none', null, '09:30', '17:00', true, array[]::int[], array[]::text[], array['nra-todaiji']::text[], array[]::text[], array['todaiji.or.jp']::text[], 'draft'),
  ('nra-ukimido', 'nara-city', 'Ukimido Pavilion', '浮見堂', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8405, 34.6805), 4326)::extensions.geography, 'kintetsu-nara', 12, array['nature']::interest_tag[], 0.05, 0.2, 0.6, 0.3, null, 10, 20, 30, array[]::text[], 'A few people on the bridge; deer at the water''s edge.', array[]::text[], array[]::text[], 'A hexagonal pavilion on a pond in the southern half of the park, lit at night and ringed with cherry trees in April. Ten minutes, on the way between Kasuga Taisha and Naramachi.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['nra-nara-park']::text[], array['sakura']::text[], array['wikivoyage']::text[], 'draft'),
  ('nra-saidaiji', 'nara-city', 'Saidai-ji', '西大寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.7815, 34.6935), 4326)::extensions.geography, null, null, array['shrines', 'history']::interest_tag[], 0.15, 0.15, 0.75, 0.4, null, 20, 40, 60, array[]::text[], 'Empty outside its tea festivals.', array[]::text[], array[]::text[], 'The ''Great Western Temple'' that once balanced Todai-ji in the east, now a quiet compound three minutes from Yamato-Saidaiji station — the Kintetsu junction you change at anyway. Known for the Ochamori ceremony, where tea is drunk from a bowl the size of a basin.', 800, 'none', null, '08:30', '16:30', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['saidaiji.or.jp']::text[], 'draft'),
  ('nra-hokkeji', 'nara-city', 'Hokke-ji', '法華寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8005, 34.6935), 4326)::extensions.geography, null, null, array['shrines', 'history']::interest_tag[], 0.15, 0.1, 0.85, 0.4, null, 20, 30, 50, array[]::text[], 'You may be the only visitor.', array[]::text[], array[]::text[], 'A convent founded by Empress Komyo in 745 on the site of her father''s mansion, with a small garden and a famous Eleven-headed Kannon shown only a few weeks a year. Ten minutes by bus from either Nara station, next to the Heijo Palace site.', 700, 'none', null, '09:00', '16:30', false, array[]::int[], array[]::text[], array['nra-heijo-palace']::text[], array[]::text[], array['hokkeji-nara.jp']::text[], 'draft'),
  ('nra-harushika', 'nara-city', 'Harushika sake brewery', '春鹿醸造元', 'food', extensions.ST_SetSRID(extensions.ST_MakePoint(135.832, 34.6785), 4326)::extensions.geography, 'kintetsu-nara', 12, array['food']::interest_tag[], 0.05, 0.3, 0.6, 0.4, null, 20, 30, 45, array[]::text[], 'A short wait for a tasting slot on weekend afternoons.', array[]::text[], array[]::text[], 'Five hundred yen buys a tasting of five sakes and you keep the glass. In Naramachi, and the brewery has been here since 1884 — Nara is where sake as we know it was first brewed.', 500, 'none', null, '10:00', '17:00', false, array[]::int[], array[]::text[], array['nra-naramachi']::text[], array[]::text[], array['harushika.com']::text[], 'draft'),
  ('nra-higashimuki', 'nara-city', 'Higashimuki arcade', '東向商店街', 'shopping', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8285, 34.6825), 4326)::extensions.geography, 'kintetsu-nara', 1, array['shopping', 'food']::interest_tag[], 0.15, 0.6, 0.1, 0.3, null, 15, 30, 60, array[]::text[], 'Busy in the middle of the day; it is the main way from the station to the park.', array[]::text[], array[]::text[], 'A covered street from the Kintetsu station exit down to Sanjo-dori — lunch, kakinoha-zushi (mackerel pressed in persimmon leaves), deer souvenirs. Not a destination; the practical answer to ''where do we eat''.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['nra-nakatanidou']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('nra-byakugoji', 'nara-city', 'Byakugo-ji', '白毫寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(135.8475, 34.6715), 4326)::extensions.geography, null, null, array['shrines', 'nature']::interest_tag[], 0.35, 0.1, 0.9, 0.4, 0.4, 20, 40, 60, array[]::text[], 'Empty, except for a week or two when the camellias are out.', array[]::text[], array['limited_mobility']::text[], 'Stone steps up between hedges to a terrace with a view over the whole Nara basin — the reason to come. Twenty-five minutes'' walk south-east of the park; pair it with Shin-Yakushi-ji, ten minutes away.', 500, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['nra-shin-yakushiji']::text[], array['sakura']::text[], array['wikivoyage']::text[], 'draft')
insert into places (id, city_id, name, name_ja, category, coords, nearest_station, station_walk_min, interest_tags, energy, crowd_level, discovery, signature, physical_demand, duration_taste_min, duration_typical_min, duration_full_min, best_window, crowd_note, worth_it_if, skip_if, local_tip, cost_jpy, booking_req, booking_lead_days, opens_at, closes_at, hours_vary, closed_weekdays, conflicts_with, pairs_with, seasons, sources, verification_status) values
  ('hir-peace-park', 'hiroshima-city', 'Peace Memorial Park', '平和記念公園', 'memorial', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4525, 34.3925), 4326)::extensions.geography, 'genbaku-domu-mae', 3, array['history']::interest_tag[], 0.25, 0.6, 0.05, 0.95, null, 30, 75, 150, array[]::text[], 'Busy but never noisy. School groups in the morning; quiet after five.', array[]::text[], array[]::text[], 'Walk it slowly, north to south: the Dome, the Children''s Monument, the Cenotaph, then the museum. Allow the whole morning with the museum. It is free and always open.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['hir-atomic-dome', 'hir-peace-museum', 'hir-childrens-monument']::text[], array[]::text[], array['hpmmuseum.jp']::text[], 'draft'),
  ('hir-atomic-dome', 'hiroshima-city', 'Atomic Bomb Dome', '原爆ドーム', 'memorial', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4536, 34.3955), 4326)::extensions.geography, 'genbaku-domu-mae', 1, array['history']::interest_tag[], 0.1, 0.7, 0.05, 0.95, null, 15, 30, 45, array['before 08:30', 'after 18:00']::text[], 'Coach groups from nine. At dawn or after dark it is you and the building.', array[]::text[], array[]::text[], 'You cannot go in; you walk around it. Come early or at night when it is lit, and stand on the far bank of the river for the view the photographs use.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['hir-peace-park']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-peace-museum', 'hiroshima-city', 'Peace Memorial Museum', '広島平和記念資料館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(132.453, 34.3915), 4326)::extensions.geography, 'genbaku-domu-mae', 8, array['history']::interest_tag[], 0.15, 0.85, 0.05, 0.95, null, 60, 100, 150, array['before 09:00']::text[], 'The queue to get in can be an hour by late morning; the exhibits inside are shoulder to shoulder. At 8:30 you walk straight in.', array[]::text[], array[]::text[], 'Two hundred yen and the reason to come to Hiroshima. It is hard. Go first thing, before you are tired, and give yourself the rest of the morning to sit by the river afterwards.', 200, 'none', null, '08:30', '18:00', true, array[]::int[], array[]::text[], array['hir-peace-park']::text[], array[]::text[], array['hpmmuseum.jp']::text[], 'draft'),
  ('hir-childrens-monument', 'hiroshima-city', 'Children''s Peace Monument', '原爆の子の像', 'memorial', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4525, 34.3935), 4326)::extensions.geography, 'genbaku-domu-mae', 5, array['history']::interest_tag[], 0.05, 0.6, 0.1, 0.7, null, 10, 15, 30, array[]::text[], 'Groups of children ringing the bell; the glass cases of paper cranes around it.', array[]::text[], array[]::text[], 'Sadako Sasaki''s statue, and the millions of paper cranes sent every year from schools around the world. Fold one before you come; there is a place to leave it.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['hir-peace-park']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-memorial-hall', 'hiroshima-city', 'Peace Memorial Hall for the Victims', '国立広島原爆死没者追悼平和祈念館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(132.452, 34.392), 4326)::extensions.geography, 'genbaku-domu-mae', 6, array['history']::interest_tag[], 0.1, 0.3, 0.5, 0.6, null, 20, 40, 60, array[]::text[], 'Quiet — most people go to the museum and miss this.', array[]::text[], array[]::text[], 'Free, underground, and a different register from the museum: a single circular room and the names. If the museum was too much, this is where to sit.', 0, 'none', null, '08:30', '17:00', true, array[]::int[], array[]::text[], array['hir-peace-museum']::text[], array[]::text[], array['hiro-tsuitokinenkan.go.jp']::text[], 'draft'),
  ('hir-orizuru-tower', 'hiroshima-city', 'Orizuru Tower', 'おりづるタワー', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4548, 34.3948), 4326)::extensions.geography, 'genbaku-domu-mae', 2, array['popculture']::interest_tag[], 0.1, 0.4, 0.3, 0.5, null, 30, 45, 75, array[]::text[], 'Rarely a wait.', array[]::text[], array[]::text[], 'The open-air roof looks straight down on the Dome and across to Miyajima on a clear day. Expensive for what it is; the paper-crane wall you fold and drop into is the memorable part. Skip if money is tight.', 2200, 'none', null, '10:00', '18:00', false, array[]::int[], array[]::text[], array['hir-atomic-dome']::text[], array[]::text[], array['orizurutower.jp']::text[], 'draft'),
  ('hir-castle', 'hiroshima-city', 'Hiroshima Castle', '広島城', 'castle', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4593, 34.4027), 4326)::extensions.geography, 'kamiyacho-nishi', 12, array['history']::interest_tag[], 0.3, 0.4, 0.3, 0.5, null, 30, 60, 90, array[]::text[], 'Comfortable. Locals walk the moat path; visitors are few.', array[]::text[], array[]::text[], 'A 1958 reconstruction — the original was destroyed by the bomb — with a modest museum and a good view from the top. The grounds and moat are free and the better part. Twenty minutes from the Peace Park on foot.', 0, 'none', null, '09:00', '16:30', true, array[]::int[], array[]::text[], array['hir-gokoku-shrine']::text[], array['sakura']::text[], array['rijo-castle.jp']::text[], 'draft'),
  ('hir-gokoku-shrine', 'hiroshima-city', 'Hiroshima Gokoku Shrine', '広島護国神社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(132.459, 34.401), 4326)::extensions.geography, 'kamiyacho-nishi', 12, array['shrines']::interest_tag[], 0.1, 0.3, 0.5, 0.3, null, 10, 20, 30, array[]::text[], 'Quiet except at New Year, when half the city comes.', array[]::text[], array[]::text[], 'Inside the castle grounds; the Carp baseball team prays here before each season. Ten minutes on the way to the keep.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['hir-castle']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-shukkeien', 'hiroshima-city', 'Shukkeien Garden', '縮景園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(132.468, 34.4), 4326)::extensions.geography, 'shukkeien-mae', 2, array['nature']::interest_tag[], 0.2, 0.3, 0.5, 0.6, null, 30, 50, 80, array[]::text[], 'Calm. Busiest for the maples in late November and still not crowded.', array[]::text[], array[]::text[], 'A 1620 stroll garden, rebuilt after the bomb, with a pond you cross on a rainbow-arched bridge. The best hour of quiet in Hiroshima. The prefectural art museum is next door.', 260, 'none', null, '09:00', '17:00', true, array[]::int[], array[]::text[], array['hir-prefectural-art']::text[], array['koyo', 'sakura']::text[], array['shukkeien.jp']::text[], 'draft'),
  ('hir-prefectural-art', 'hiroshima-city', 'Hiroshima Prefectural Art Museum', '広島県立美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4672, 34.3997), 4326)::extensions.geography, 'shukkeien-mae', 2, array['art']::interest_tag[], 0.1, 0.2, 0.5, 0.4, null, 40, 75, 120, array[]::text[], 'Quiet.', array[]::text[], array[]::text[], 'Closed Mondays. Dalí''s ''Dream of Venus'' and a strong local collection; the third-floor window frames Shukkeien. A combined ticket with the garden is cheaper.', 510, 'none', null, '09:00', '17:00', false, array[1]::int[], array[]::text[], array['hir-shukkeien']::text[], array[]::text[], array['hpam.jp']::text[], 'draft'),
  ('hir-museum-of-art', 'hiroshima-city', 'Hiroshima Museum of Art', 'ひろしま美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(132.46, 34.399), 4326)::extensions.geography, 'kamiyacho-nishi', 8, array['art']::interest_tag[], 0.1, 0.2, 0.55, 0.5, null, 40, 75, 120, array[]::text[], 'Quiet; a few people per room.', array[]::text[], array[]::text[], 'Closed Mondays. A small round building with Monet, Van Gogh, Picasso — bought by a bank as a gift to the city after the war. The best small art museum in western Japan.', 1500, 'none', null, '09:00', '17:00', false, array[1]::int[], array[]::text[], array['hir-castle']::text[], array[]::text[], array['hiroshima-museum.jp']::text[], 'draft'),
  ('hir-hondori', 'hiroshima-city', 'Hondori', '本通', 'shopping', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4595, 34.393), 4326)::extensions.geography, 'hondori', 1, array['shopping', 'food']::interest_tag[], 0.2, 0.6, 0.2, 0.4, null, 20, 45, 90, array[]::text[], 'The city''s main covered street; busy after work and at weekends, never a crush.', array[]::text[], array[]::text[], 'A kilometre of shops under a roof from the Peace Park to the department stores. Useful for a rainy hour; the okonomiyaki floors of the buildings around it are the reason to come.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['hir-okonomimura']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-okonomimura', 'hiroshima-city', 'Okonomimura', 'お好み村', 'food', extensions.ST_SetSRID(extensions.ST_MakePoint(132.462, 34.3915), 4326)::extensions.geography, 'hatchobori', 5, array['food']::interest_tag[], 0.05, 0.7, 0.3, 0.7, null, 40, 60, 90, array[]::text[], 'Twenty-five stalls on three floors; at peak hours you wait for a counter seat, then it is fast.', array[]::text[], array[]::text[], 'Hiroshima okonomiyaki is layered, not mixed, with noodles inside — a different dish from Osaka''s. Pick any stall with a free seat; they are all decent. Cash.', 0, 'none', null, '11:00', '22:00', false, array[]::int[], array[]::text[], array['hir-hondori']::text[], array[]::text[], array['okonomimura.jp']::text[], 'draft'),
  ('hir-ekie', 'hiroshima-city', 'Ekie okonomiyaki floor', 'エキエ', 'food', extensions.ST_SetSRID(extensions.ST_MakePoint(132.475, 34.3978), 4326)::extensions.geography, 'hiroshima', 1, array['food']::interest_tag[], 0.05, 0.6, 0.3, 0.4, null, 30, 45, 60, array[]::text[], 'Queues at lunchtime, quick turnover.', array[]::text[], array[]::text[], 'Inside the station: a floor of okonomiyaki counters, good ones, ten metres from the Shinkansen gate. The practical answer when you have forty minutes before a train.', 0, 'none', null, '11:00', '22:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-mazda-museum', 'hiroshima-city', 'Mazda Museum', 'マツダミュージアム', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(132.5038, 34.378), 4326)::extensions.geography, null, null, array['popculture', 'history']::interest_tag[], 0.1, 0.3, 0.6, 0.5, null, 60, 90, 90, array[]::text[], 'Small guided groups; never crowded.', array[]::text[], array[]::text[], 'Weekday guided tours only, booked ahead online; you see the assembly line, which is the point. Twenty minutes from the station on the JR Kure line to Mukainada. For people who like factories.', 0, 'required', 14, '09:00', '16:00', false, array[0, 6]::int[], array[]::text[], array[]::text[], array[]::text[], array['mazda.com']::text[], 'draft'),
  ('hir-mitaki-dera', 'hiroshima-city', 'Mitaki-dera', '三瀧寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(132.439, 34.414), 4326)::extensions.geography, null, null, array['shrines', 'nature']::interest_tag[], 0.5, 0.15, 0.85, 0.6, 0.5, 30, 60, 90, array[]::text[], 'A handful of locals. On November weekends, a few more.', array[]::text[], array['limited_mobility']::text[], 'A temple on a wooded hillside with three waterfalls and a pagoda moved here from Wakayama as a memorial. The best maples in Hiroshima and almost nobody knows. Fifteen minutes'' walk uphill from Mitaki station.', 0, 'none', null, '08:00', '17:00', true, array[]::int[], array[]::text[], array[]::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-hijiyama', 'hiroshima-city', 'Hijiyama Park', '比治山公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(132.472, 34.385), 4326)::extensions.geography, null, null, array['nature', 'art']::interest_tag[], 0.4, 0.2, 0.6, 0.4, 0.4, 30, 60, 120, array[]::text[], 'Quiet; families at weekends, cherry-blossom picnics in April.', array[]::text[], array['limited_mobility']::text[], 'A wooded hill east of the centre with the city''s contemporary art museum on top and a view over the delta. A good place to walk off the Peace Park. Fifteen minutes from Hijiyama-shita tram stop, uphill.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['hir-mocha']::text[], array['sakura', 'koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-mocha', 'hiroshima-city', 'Hiroshima City Museum of Contemporary Art', '広島市現代美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4735, 34.3845), 4326)::extensions.geography, null, null, array['art']::interest_tag[], 0.15, 0.2, 0.6, 0.4, null, 40, 75, 120, array[]::text[], 'Quiet.', array[]::text[], array[]::text[], 'Closed Mondays. Reopened 2023 after renovation, on top of Hijiyama; a strong collection on the theme of the city. Kurokawa''s building is half the reason.', 400, 'none', null, '10:00', '17:00', false, array[1]::int[], array[]::text[], array['hir-hijiyama']::text[], array[]::text[], array['hiroshima-moca.jp']::text[], 'draft'),
  ('hir-fudoin', 'hiroshima-city', 'Fudoin', '不動院', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(132.475, 34.427), 4326)::extensions.geography, null, null, array['shrines', 'history']::interest_tag[], 0.15, 0.1, 0.9, 0.5, null, 15, 30, 45, array[]::text[], 'Empty.', array[]::text[], array[]::text[], 'The only National Treasure building in Hiroshima that survived the bomb — a 1540 hall four kilometres from the hypocentre. Nobody comes. Astram line to Fudoin-mae, two minutes.', 0, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-toshogu', 'hiroshima-city', 'Hiroshima Toshogu', '広島東照宮', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(132.477, 34.4045), 4326)::extensions.geography, 'hiroshima', 10, array['shrines']::interest_tag[], 0.3, 0.15, 0.7, 0.4, 0.3, 15, 30, 45, array[]::text[], 'Empty apart from local walkers.', array[]::text[], array[]::text[], 'Up a long staircase behind the station, with a view back over the city and a shrine that survived 1945 with its gate intact. Ten minutes from the Shinkansen — a good use of a spare half hour.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-kagura', 'hiroshima-city', 'Hiroshima Kagura night', '広島神楽定期公演', 'performance', extensions.ST_SetSRID(extensions.ST_MakePoint(132.458, 34.394), 4326)::extensions.geography, 'kamiyacho-nishi', 3, array['history', 'offbeat']::interest_tag[], 0.05, 0.4, 0.7, 0.6, null, 60, 75, 90, array['after 17:30']::text[], 'A few hundred seats and rarely full on an ordinary Wednesday.', array[]::text[], array[]::text[], 'Every Wednesday evening at the Prefectural Culture Centre: masked, drum-driven mythological dance from the mountain villages — a hero, a serpent, a great deal of smoke. Hiroshima''s own tradition and the best-value ticket in the city. English synopsis on the sheet.', 1500, 'recommended', 7, '19:00', '20:30', false, array[0, 1, 2, 4, 5, 6]::int[], array[]::text[], array[]::text[], array[]::text[], array['hiroshima-kankou.com']::text[], 'draft'),
  ('hir-nagarekawa', 'hiroshima-city', 'Nagarekawa', '流川', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4665, 34.3905), 4326)::extensions.geography, 'hatchobori', 5, array['nightlife', 'food']::interest_tag[], 0.15, 0.6, 0.3, 0.5, null, 30, 90, 180, array['after 17:30']::text[], 'Quiet until eight, then busy until late; Friday and Saturday are the loud nights.', array[]::text[], array[]::text[], 'The bar district: several hundred small places across a few blocks, most of them a counter and ten stools. Grilled oysters and local sake are the order. Pick a door with a handwritten menu and go in.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['hir-okonomimura']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-carp-game', 'hiroshima-city', 'Carp game at Mazda Stadium', 'マツダスタジアム', 'sport', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4845, 34.3925), 4326)::extensions.geography, 'hiroshima', 10, array['popculture']::interest_tag[], 0.15, 0.8, 0.4, 0.6, null, 90, 180, 240, array[]::text[], 'Sells out most weekends; weeknight games are easier and the atmosphere is the same.', array[]::text[], array[]::text[], 'Hiroshima''s baseball team has the loudest, most coordinated fans in Japan, and a home game is the best evening the city has from late March to early October. Buy online ahead — the cheap outfield seats are the fun ones. Ten minutes'' walk from the station along a road painted red.', 2500, 'required', 30, null, null, false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['carp.co.jp']::text[], 'draft'),
  ('hir-ogonzan', 'hiroshima-city', 'Mount Ogonzan', '黄金山', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(132.4885, 34.3745), 4326)::extensions.geography, null, null, array['nature']::interest_tag[], 0.5, 0.1, 0.9, 0.4, 0.5, 30, 60, 90, array['after 17:30']::text[], 'Couples in parked cars at night; otherwise nobody.', array[]::text[], array['limited_mobility']::text[], 'A 220-metre hill south-east of the centre with the city''s night view: the whole delta, the port, and the Inland Sea islands. A steep forty-minute walk up from the bottom, or a taxi to the top. Bring the walk down for the lights.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('hir-botanical-garden', 'hiroshima-city', 'Hiroshima Botanical Garden', '広島市植物公園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(132.397, 34.372), 4326)::extensions.geography, null, null, array['nature']::interest_tag[], 0.3, 0.2, 0.7, 0.3, null, 45, 90, 150, array[]::text[], 'Families at weekends; near-empty on weekdays.', array[]::text[], array[]::text[], 'Closed Fridays. A large hillside garden with a good greenhouse, half an hour west of the centre by JR to Itsukaichi and a bus up. A rainy-day or with-children option, not a must; the cherry avenue is real in early April.', 510, 'none', null, '09:00', '16:30', false, array[5]::int[], array[]::text[], array[]::text[], array['sakura']::text[], array['hiroshima-bot.jp']::text[], 'draft')
insert into places (id, city_id, name, name_ja, category, coords, nearest_station, station_walk_min, interest_tags, energy, crowd_level, discovery, signature, physical_demand, duration_taste_min, duration_typical_min, duration_full_min, best_window, crowd_note, worth_it_if, skip_if, local_tip, cost_jpy, booking_req, booking_lead_days, opens_at, closes_at, hours_vary, closed_weekdays, conflicts_with, pairs_with, seasons, sources, verification_status) values
  ('miy-itsukushima', 'miyajima', 'Itsukushima Shrine', '厳島神社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(132.3198, 34.296), 4326)::extensions.geography, 'miyajima-pier', 12, array['shrines', 'nature']::interest_tag[], 0.2, 0.85, 0.05, 0.95, null, 30, 60, 90, array['before 09:00', 'after 16:30']::text[], 'A one-way boardwalk that moves at the pace of the slowest group. First thing and last thing it is yours.', array[]::text[], array[]::text[], 'Built over the water, so the tide decides what you see: at high tide the shrine floats, at low tide you can walk out to the torii. Check the tide table before you choose the day. The 6:30 opening is the one to make.', 300, 'none', null, '06:30', '17:00', true, array[]::int[], array[]::text[], array['miy-great-torii', 'miy-daishoin']::text[], array['koyo']::text[], array['itsukushimajinja.jp']::text[], 'draft'),
  ('miy-great-torii', 'miyajima', 'The Great Torii', '大鳥居', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(132.3185, 34.2985), 4326)::extensions.geography, 'miyajima-pier', 12, array['shrines', 'nature']::interest_tag[], 0.1, 0.8, 0.05, 0.9, null, 15, 30, 60, array[]::text[], 'Everyone on the island is looking at it, all day. The beach is wide enough.', array[]::text[], array[]::text[], 'Free, and visible from the ferry before you land. Low tide lets you walk out and touch it; high tide at sunset is the photograph. The two happen about six hours apart — you can have both in one day.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['miy-itsukushima']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('miy-daishoin', 'miyajima', 'Daisho-in', '大聖院', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(132.317, 34.2935), 4326)::extensions.geography, 'miyajima-pier', 20, array['shrines', 'nature']::interest_tag[], 0.35, 0.25, 0.6, 0.6, 0.4, 30, 60, 90, array[]::text[], 'A fraction of the shrine''s crowd. The 500 small statues in knitted hats line the steps.', array[]::text[], array[]::text[], 'Up the hill behind the shrine, free, and the most rewarding hour on the island after the shrine itself. Spin the sutra wheels on the stairs. The Misen trail starts from here if you are walking up.', 0, 'none', null, '08:00', '17:00', false, array[]::int[], array[]::text[], array['miy-itsukushima']::text[], array['koyo']::text[], array['galilei.ne.jp/daisyoin']::text[], 'draft'),
  ('miy-senjokaku', 'miyajima', 'Senjokaku & the pagoda', '千畳閣', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(132.3215, 34.2985), 4326)::extensions.geography, 'miyajima-pier', 12, array['history', 'nature']::interest_tag[], 0.15, 0.3, 0.5, 0.5, null, 15, 30, 45, array[]::text[], 'Quiet — people photograph the pagoda from below and rarely climb the steps.', array[]::text[], array[]::text[], 'A vast, unfinished wooden hall from 1587 — Hideyoshi died before it was done — open on all sides, with the best breeze on the island and a view down onto the shrine roofs. A hundred yen.', 100, 'none', null, '08:30', '16:30', false, array[]::int[], array[]::text[], array['miy-itsukushima']::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('miy-omotesando', 'miyajima', 'Omotesando shopping street', '表参道商店街', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(132.321, 34.3005), 4326)::extensions.geography, 'miyajima-pier', 5, array['food', 'shopping']::interest_tag[], 0.15, 0.8, 0.1, 0.5, null, 20, 40, 75, array[]::text[], 'Full from late morning until the last day-trippers leave. Early evening it empties out entirely.', array[]::text[], array[]::text[], 'Grilled oysters, momiji manju (maple-leaf cakes), and the world''s largest rice scoop. The stalls shut around five; if you are staying the night, the island after six is a different place.', 0, 'none', null, '10:00', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['wikivoyage']::text[], 'draft'),
  ('miy-momijidani', 'miyajima', 'Momijidani Park', '紅葉谷公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(132.322, 34.2945), 4326)::extensions.geography, 'momijidani', 2, array['nature']::interest_tag[], 0.25, 0.4, 0.4, 0.6, null, 20, 40, 75, array[]::text[], 'Busy in the last two weeks of November for the maples it is named for; otherwise a quiet valley with deer.', array[]::text[], array[]::text[], 'The maple valley at the foot of Mount Misen, where the ropeway starts. Come in late November or come for the walk to the ropeway; either way it is fifteen minutes from the shrine.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['miy-misen']::text[], array['koyo']::text[], array['wikivoyage']::text[], 'draft'),
  ('miy-misen', 'miyajima', 'Mount Misen', '弥山', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(132.318, 34.279), 4326)::extensions.geography, 'momijidani', 5, array['nature', 'shrines']::interest_tag[], 0.6, 0.5, 0.3, 0.8, 0.6, 90, 150, 240, array[]::text[], 'The ropeway queues on autumn weekends — an hour is possible. Weekday mornings you walk on.', array[]::text[], array['limited_mobility']::text[], 'Two ropeways to the top station, then a real 30-minute walk up to the summit — steps, not a stroll. The view over the Inland Sea is the best in the region. The flame in the hall near the top has burned for 1,200 years. Last ropeway down is early; check it.', 2000, 'none', null, '09:00', '16:30', false, array[]::int[], array[]::text[], array['miy-momijidani']::text[], array['koyo']::text[], array['miyajima-ropeway.info']::text[], 'draft'),
  ('miy-aquarium', 'miyajima', 'Miyajima Aquarium', '宮島水族館', 'aquarium', extensions.ST_SetSRID(extensions.ST_MakePoint(132.315, 34.292), 4326)::extensions.geography, 'miyajima-pier', 25, array['nature']::interest_tag[], 0.15, 0.4, 0.4, 0.3, null, 45, 75, 100, array[]::text[], 'Families; comfortable.', array[]::text[], array[]::text[], 'Small and local — Inland Sea fish, oyster farming, a finless porpoise. Good with children or on a wet afternoon; otherwise the island has better uses for the time.', 1420, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['miyajima-aqua.jp']::text[], 'draft')
insert into places (id, city_id, name, name_ja, category, coords, nearest_station, station_walk_min, interest_tags, energy, crowd_level, discovery, signature, physical_demand, duration_taste_min, duration_typical_min, duration_full_min, best_window, crowd_note, worth_it_if, skip_if, local_tip, cost_jpy, booking_req, booking_lead_days, opens_at, closes_at, hours_vary, closed_weekdays, conflicts_with, pairs_with, seasons, sources, verification_status) values
  ('hmj-castle', 'himeji', 'Himeji Castle', '姫路城', 'castle', extensions.ST_SetSRID(extensions.ST_MakePoint(134.6939, 34.8394), 4326)::extensions.geography, 'himeji', 15, array['history']::interest_tag[], 0.5, 0.8, 0.05, 0.95, 0.5, 60, 120, 180, array['before 09:30']::text[], 'Entry to the keep is capped on busy days and the wait inside on the stairs can be long. At opening you climb freely.', array[]::text[], array[]::text[], 'The finest surviving castle in Japan, original not rebuilt, and white enough to hurt your eyes. Six floors of steep wooden stairs in socks. Straight up the main road from the station — you can see it from the platform. Lockers at the station for luggage.', 2500, 'none', null, '09:00', '17:00', true, array[]::int[], array[]::text[], array['hmj-kokoen']::text[], array['sakura']::text[], array['himejicastle.jp']::text[], 'draft'),
  ('hmj-kokoen', 'himeji', 'Koko-en Garden', '好古園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(134.689, 34.8375), 4326)::extensions.geography, 'himeji', 15, array['nature']::interest_tag[], 0.2, 0.3, 0.4, 0.5, null, 30, 50, 80, array[]::text[], 'Calm even when the castle is packed.', array[]::text[], array[]::text[], 'Nine walled gardens next to the castle on the site of the old samurai residences, built in 1992 and better than that sounds. The combined ticket with the castle saves a little. Tea house on the pond.', 310, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['hmj-castle']::text[], array['koyo']::text[], array['himeji-machishin.jp/ryokka/kokoen']::text[], 'draft'),
  ('hmj-engyoji', 'himeji', 'Engyo-ji', '圓教寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(134.647, 34.865), 4326)::extensions.geography, 'shosha-ropeway', 5, array['shrines', 'nature', 'history']::interest_tag[], 0.5, 0.2, 0.7, 0.7, 0.5, 60, 120, 180, array[]::text[], 'A few pilgrims and walkers. The Last Samurai was filmed here and it is still empty.', array[]::text[], array['limited_mobility']::text[], 'A mountaintop temple complex reached by bus and ropeway, then a twenty-minute uphill walk through forest. Wooden halls on stilts, nobody about. Half a day from Himeji station; the castle is the morning, this is the afternoon.', 500, 'none', null, '08:30', '17:00', true, array[]::int[], array[]::text[], array[]::text[], array['koyo']::text[], array['shosha.or.jp']::text[], 'draft'),
  ('hmj-city-art-museum', 'himeji', 'Himeji City Museum of Art', '姫路市立美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(134.698, 34.841), 4326)::extensions.geography, 'himeji', 20, array['art']::interest_tag[], 0.1, 0.2, 0.5, 0.3, null, 30, 60, 90, array[]::text[], 'Quiet.', array[]::text[], array[]::text[], 'Closed Mondays. A red-brick former army arsenal beside the castle moat, with a decent Belgian collection. The lawn in front is the best angle on the castle for a photograph.', 300, 'none', null, '10:00', '17:00', false, array[1]::int[], array[]::text[], array['hmj-castle']::text[], array[]::text[], array['city.himeji.lg.jp/art']::text[], 'draft'),
  ('hmj-history-museum', 'himeji', 'Hyogo Prefectural Museum of History', '兵庫県立歴史博物館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(134.6975, 34.8425), 4326)::extensions.geography, 'himeji', 20, array['history']::interest_tag[], 0.1, 0.2, 0.5, 0.3, null, 30, 60, 90, array[]::text[], 'Quiet.', array[]::text[], array[]::text[], 'Closed Mondays. Kenzo Tange''s building, with castle models and a room where you can try on armour. Only if you have time after the castle and Koko-en; the reflection of the keep in its glass wall is free.', 200, 'none', null, '10:00', '17:00', false, array[1]::int[], array[]::text[], array[]::text[], array[]::text[], array['hyogo-c.ed.jp/~rekihaku-bo']::text[], 'draft'),
  ('hmj-otemae-dori', 'himeji', 'Otemae-dori', '大手前通り', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(134.691, 34.833), 4326)::extensions.geography, 'himeji', 1, array['shopping', 'food']::interest_tag[], 0.2, 0.4, 0.1, 0.3, null, 15, 20, 40, array[]::text[], 'A wide boulevard, never crowded.', array[]::text[], array[]::text[], 'The straight kilometre from the station to the castle gate, with the keep framed at the end of it the whole way. Walk it rather than take the bus; the covered arcades either side have lunch.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['hmj-castle']::text[], array[]::text[], array['wikivoyage']::text[], 'draft')
insert into places (id, city_id, name, name_ja, category, coords, nearest_station, station_walk_min, interest_tags, energy, crowd_level, discovery, signature, physical_demand, duration_taste_min, duration_typical_min, duration_full_min, best_window, crowd_note, worth_it_if, skip_if, local_tip, cost_jpy, booking_req, booking_lead_days, opens_at, closes_at, hours_vary, closed_weekdays, conflicts_with, pairs_with, seasons, sources, verification_status) values
  ('tky-sensoji', 'tokyo-city', 'Senso-ji', '浅草寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7967, 35.7148), 4326)::extensions.geography, 'asakusa', 5, array['shrines', 'history']::interest_tag[], 0.25, 0.95, 0.05, 0.95, null, 30, 60, 90, array['before 08:00', 'after 17:30']::text[], 'Nakamise-dori is shoulder to shoulder from ten until the shops shut. After dark the lit hall and pagoda are nearly empty.', array['photography', 'early_riser']::text[], array[]::text[], 'The grounds never close; the main hall opens 06:00 (06:30 October to March) and shuts at 17:00. Come at dusk, when the shops pull their shutters down and the buildings are lit.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-kappabashi', 'tky-skytree']::text[], array[]::text[], array['senso-ji.jp']::text[], 'draft'),
  ('tky-kappabashi', 'tokyo-city', 'Kappabashi Dougu Street', 'かっぱ橋道具街', 'shopping', extensions.ST_SetSRID(extensions.ST_MakePoint(139.788, 35.7128), 4326)::extensions.geography, 'tawaramachi', 5, array['shopping', 'offbeat']::interest_tag[], 0.2, 0.4, 0.5, 0.4, null, 20, 60, 90, array[]::text[], 'Weekday trade buyers and a few visitors; never a crush.', array[]::text[], array[]::text[], 'The street that supplies Tokyo''s kitchens: knives, plastic food samples, lacquer and ceramics at trade prices. Each shop keeps its own hours, so come in the daytime; about seven in ten close on Sundays and holidays.', 0, 'none', null, '10:00', '17:00', false, array[]::int[], array[]::text[], array['tky-sensoji']::text[], array[]::text[], array['kappabashi.or.jp']::text[], 'draft'),
  ('tky-skytree', 'tokyo-city', 'Tokyo Skytree', '東京スカイツリー', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(139.8107, 35.7101), 4326)::extensions.geography, 'oshiage', 3, array['popculture']::interest_tag[], 0.15, 0.7, 0.05, 0.6, null, 45, 90, 120, array['after 17:30']::text[], 'Ticket queues at weekends and around sunset; weekday mornings you walk straight up.', array[]::text[], array[]::text[], 'At 350 m the Tembo Deck is the highest view in Tokyo. Dated tickets online are cheaper than at the counter and the price changes with the day and hour; the higher Tembo Galleria needs its own or a combined ticket and adds little. Opens an hour earlier at weekends.', 1800, 'recommended', null, '10:00', '22:00', false, array[]::int[], array['tky-shibuya-sky']::text[], array['tky-sensoji']::text[], array[]::text[], array['tokyo-skytree.jp']::text[], 'draft'),
  ('tky-edo-tokyo-museum', 'tokyo-city', 'Edo-Tokyo Museum', '江戸東京博物館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7957, 35.6966), 4326)::extensions.geography, 'ryogoku', 3, array['history']::interest_tag[], 0.3, 0.4, 0.3, 0.5, null, 60, 120, 180, array[]::text[], 'School groups on weekday mornings; afternoons are calm.', array[]::text[], array[]::text[], 'The best single place to see how Edo became Tokyo — a full-size half of the Nihonbashi bridge, a kabuki theatre front, scale models of the old city. It reopened in March 2026 after a long renovation. Open until 19:30 on Saturdays; special exhibitions cost extra.', 800, 'none', null, '09:30', '17:30', false, array[1]::int[], array[]::text[], array['tky-kokugikan', 'tky-hokusai-museum']::text[], array[]::text[], array['edo-tokyo-museum.or.jp']::text[], 'draft'),
  ('tky-kokugikan', 'tokyo-city', 'Ryogoku Kokugikan (sumo)', '両国国技館', 'sport', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7934, 35.6969), 4326)::extensions.geography, 'ryogoku', 2, array['history', 'popculture']::interest_tag[], 0.2, 0.7, 0.2, 0.7, null, 120, 240, 480, array['after 14:00']::text[], 'Sold out for the top-division hours; the morning bouts of the junior ranks are played to a near-empty hall.', array[]::text[], array[]::text[], 'Tokyo''s grand tournaments are in January, May and September only, fifteen days each. Tickets go on sale five to seven weeks before and the cheap seats go on the first day. The top division enters the ring at about 15:40 and fights from about 16:10 to 18:00; the last days open later.', 3500, 'required', null, '08:45', '18:00', false, array[]::int[], array[]::text[], array['tky-edo-tokyo-museum']::text[], array[]::text[], array['sumo.or.jp']::text[], 'draft'),
  ('tky-hokusai-museum', 'tokyo-city', 'Sumida Hokusai Museum', 'すみだ北斎美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.8001, 35.6963), 4326)::extensions.geography, 'ryogoku', 9, array['art']::interest_tag[], 0.15, 0.3, 0.6, 0.4, null, 45, 60, 90, array[]::text[], 'Quiet; the special exhibitions draw more.', array[]::text[], array[]::text[], 'Hokusai was born nearby. The aluminium-clad building by Kazuyo Sejima is half the visit; the permanent gallery is small, so check which special exhibition is on.', 400, 'none', null, '09:30', '17:30', false, array[1]::int[], array[]::text[], array['tky-edo-tokyo-museum']::text[], array[]::text[], array['hokusai-museum.jp']::text[], 'draft'),
  ('tky-kiyosumi-garden', 'tokyo-city', 'Kiyosumi Gardens', '清澄庭園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7973, 35.6807), 4326)::extensions.geography, 'kiyosumi-shirakawa', 3, array['nature', 'offbeat']::interest_tag[], 0.2, 0.2, 0.6, 0.4, null, 30, 45, 60, array[]::text[], 'Rarely more than a handful of people.', array[]::text[], array[]::text[], 'Stepping stones across a big pond of turtles and herons; last entry 16:30. The streets around it are Tokyo''s coffee-roastery district — come for a garden and a good cup.', 150, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['tokyo-park.or.jp']::text[], 'draft'),
  ('tky-ueno-park', 'tokyo-city', 'Ueno Park', '上野恩賜公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7732, 35.7146), 4326)::extensions.geography, 'ueno', 3, array['nature', 'history']::interest_tag[], 0.3, 0.6, 0.1, 0.5, null, 20, 60, 120, array[]::text[], 'Comfortable most of the year. In cherry-blossom week it is the busiest hanami spot in Tokyo, with tarps laid out from dawn.', array[]::text[], array[]::text[], 'The front door to the National Museum, the art museums and the zoo. Shinobazu Pond at the south end is covered in lotus in July and August.', 0, 'none', null, '05:00', '23:00', false, array[]::int[], array[]::text[], array['tky-national-museum', 'tky-ameyoko']::text[], array['sakura']::text[], array['kensetsu.metro.tokyo.lg.jp']::text[], 'draft'),
  ('tky-national-museum', 'tokyo-city', 'Tokyo National Museum', '東京国立博物館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7766, 35.7189), 4326)::extensions.geography, 'ueno', 10, array['history', 'art']::interest_tag[], 0.35, 0.4, 0.2, 0.6, null, 60, 120, 240, array[]::text[], 'The permanent galleries are calm; a big special exhibition brings timed tickets and queues.', array[]::text[], array[]::text[], 'Start in the Honkan for samurai armour, swords and screens, then the Gallery of Horyu-ji Treasures, a quiet modern building to the left inside the main gate that most people miss. Open until 20:00 on Fridays and Saturdays.', 1000, 'none', null, '09:30', '17:00', false, array[1]::int[], array[]::text[], array['tky-ueno-park']::text[], array[]::text[], array['tnm.jp']::text[], 'draft'),
  ('tky-ameyoko', 'tokyo-city', 'Ameyoko', 'アメ横商店街', 'market', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7745, 35.71), 4326)::extensions.geography, 'ueno', 3, array['food', 'shopping']::interest_tag[], 0.2, 0.8, 0.2, 0.5, null, 20, 45, 90, array['after 17:30']::text[], 'Busy every weekend and wall to wall in the last days of December, when Tokyo buys its New Year food here.', array[]::text[], array[]::text[], 'A market street running under the tracks from Ueno to Okachimachi. Stalls by day; by night the standing bars and izakaya under the arches are the reason to come.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-ueno-park']::text[], array[]::text[], array['ameyoko.net']::text[], 'draft'),
  ('tky-yanaka', 'tokyo-city', 'Yanaka Ginza', '谷中銀座', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7663, 35.7276), 4326)::extensions.geography, 'nippori', 5, array['history', 'food', 'offbeat']::interest_tag[], 0.3, 0.4, 0.6, 0.5, null, 30, 90, 150, array[]::text[], 'A neighbourhood shopping street that visitors seek out too; it gets busy on weekend afternoons.', array[]::text[], array[]::text[], 'The old-Tokyo pocket the war missed: temples, wooden houses, a shopping street of croquettes and cats. Walk from Nippori through Yanaka Cemetery, down Yanaka Ginza and on to Nezu Shrine.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-nezu-shrine']::text[], array[]::text[], array['yanakaginza.com']::text[], 'draft'),
  ('tky-nezu-shrine', 'tokyo-city', 'Nezu Shrine', '根津神社', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7607, 35.7202), 4326)::extensions.geography, 'nezu', 5, array['shrines', 'nature']::interest_tag[], 0.15, 0.3, 0.6, 0.4, null, 15, 30, 45, array[]::text[], 'Quiet most of the year; packed during the azalea festival in April.', array[]::text[], array[]::text[], 'A lacquered 1706 shrine with a small tunnel of red torii — Fushimi Inari in miniature, without the queue. The shrine is free; the azalea garden charges ¥500–1,000 in April, depending on the bloom.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-yanaka']::text[], array[]::text[], array['nedujinja.or.jp']::text[], 'draft'),
  ('tky-rikugien', 'tokyo-city', 'Rikugien', '六義園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7468, 35.7329), 4326)::extensions.geography, 'komagome', 7, array['nature', 'history']::interest_tag[], 0.25, 0.4, 0.4, 0.5, null, 30, 60, 90, array[]::text[], 'Calm, except the weeping-cherry and autumn-maple evenings, when the light-ups queue at the gate.', array[]::text[], array[]::text[], 'An Edo-period stroll garden laid out around eighty-eight scenes from poems; last entry 16:30. The giant weeping cherry by the entrance blooms in late March. The evening light-ups in blossom and maple season are separate events with their own tickets.', 300, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array[]::text[], array['sakura', 'koyo']::text[], array['tokyo-park.or.jp']::text[], 'draft'),
  ('tky-shibamata', 'tokyo-city', 'Shibamata Taishakuten', '柴又帝釈天', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(139.8783, 35.7584), 4326)::extensions.geography, 'shibamata', 3, array['history', 'shrines', 'offbeat']::interest_tag[], 0.2, 0.3, 0.7, 0.4, null, 30, 75, 120, array[]::text[], 'Busy only on weekend afternoons and the temple''s festival days.', array[]::text[], array[]::text[], 'A lane of dango shops leads to a temple whose outer walls are covered in astonishing wood carvings — the carving gallery and garden are the reason to come. Old Tokyo as the Tora-san films remember it.', 400, 'none', null, '09:00', '16:30', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['taishakuten.com']::text[], 'draft'),
  ('tky-meiji-jingu', 'tokyo-city', 'Meiji Jingu', '明治神宮', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(139.6993, 35.6764), 4326)::extensions.geography, 'harajuku', 10, array['shrines', 'nature']::interest_tag[], 0.35, 0.7, 0.05, 0.85, null, 30, 60, 90, array['before 09:00']::text[], 'Busy all day, but the wide gravel paths absorb it. New Year''s first three days bring around three million visitors.', array[]::text[], array[]::text[], 'Gates open at sunrise and close at sunset, so the hours change every month. The forest walk in from Harajuku is the point; the inner garden''s irises bloom in June.', 0, 'none', null, '06:40', '16:00', true, array[]::int[], array[]::text[], array['tky-takeshita', 'tky-yoyogi-park']::text[], array[]::text[], array['meijijingu.or.jp']::text[], 'draft'),
  ('tky-takeshita', 'tokyo-city', 'Takeshita Street', '竹下通り', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7031, 35.6715), 4326)::extensions.geography, 'harajuku', 1, array['popculture', 'shopping', 'food']::interest_tag[], 0.2, 0.95, 0.05, 0.5, null, 15, 30, 60, array[]::text[], 'A crush on weekend afternoons; half asleep on weekday mornings, when shops are still opening.', array[]::text[], array[]::text[], 'Crêpes, rainbow candy floss and kawaii fashion in 350 metres. Fifteen minutes is enough for most adults; Cat Street, behind Omotesando, is the calmer half of Harajuku.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-meiji-jingu', 'tky-omotesando']::text[], array[]::text[], array['takeshita-street.com']::text[], 'draft'),
  ('tky-omotesando', 'tokyo-city', 'Omotesando & Cat Street', '表参道', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7088, 35.667), 4326)::extensions.geography, 'omotesando', 2, array['shopping', 'art']::interest_tag[], 0.25, 0.6, 0.3, 0.5, null, 30, 75, 120, array[]::text[], 'Busy at weekends, but a wide avenue — it never feels like Takeshita.', array[]::text[], array[]::text[], 'Tokyo''s architecture walk: Tod''s by Toyo Ito, Prada by Herzog & de Meuron, Omotesando Hills by Tadao Ando. Window-shopping as a design tour; Cat Street runs behind it down to Shibuya.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-takeshita', 'tky-nezu-museum']::text[], array[]::text[], array['gotokyo.org']::text[], 'draft'),
  ('tky-nezu-museum', 'tokyo-city', 'Nezu Museum', '根津美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7173, 35.6623), 4326)::extensions.geography, 'omotesando', 8, array['art', 'nature']::interest_tag[], 0.2, 0.4, 0.6, 0.5, null, 45, 90, 120, array[]::text[], 'Calm, except in late April and May, when Korin''s Irises screen is shown and the garden irises bloom.', array[]::text[], array[]::text[], 'A Kengo Kuma building and a hillside garden with teahouses and stone lanterns — the garden alone is worth the ticket. Book a time online; walk-ins get in only if there is room, and pay more. Closed between exhibitions.', 1400, 'recommended', 3, '10:00', '17:00', false, array[1]::int[], array[]::text[], array['tky-omotesando']::text[], array[]::text[], array['nezu-muse.or.jp']::text[], 'draft'),
  ('tky-yoyogi-park', 'tokyo-city', 'Yoyogi Park', '代々木公園', 'park', extensions.ST_SetSRID(extensions.ST_MakePoint(139.6949, 35.6717), 4326)::extensions.geography, 'harajuku', 5, array['nature', 'offbeat']::interest_tag[], 0.25, 0.5, 0.2, 0.4, null, 20, 60, 120, array[]::text[], 'Sunday afternoons are the show; weekdays it is just a big park.', array[]::text[], array[]::text[], 'On Sundays the rockabilly dancers by the Harajuku entrance, drum circles and picnics are Tokyo at leisure. Weekend food festivals fill the event plaza across the road.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-meiji-jingu']::text[], array['sakura']::text[], array['tokyo-park.or.jp']::text[], 'draft'),
  ('tky-shibuya-crossing', 'tokyo-city', 'Shibuya Crossing', '渋谷スクランブル交差点', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7005, 35.6595), 4326)::extensions.geography, 'shibuya', 1, array['popculture', 'nightlife']::interest_tag[], 0.1, 0.95, 0, 0.8, null, 10, 30, 60, array['after 17:30']::text[], 'Crowds are the point. Drinking in the street around the station is banned every night from 18:00 to 05:00, and police manage the crowds at Halloween and New Year.', array[]::text[], array[]::text[], 'Look from above first, then cross with everyone. The Hachiko statue is at the station exit; the alleys up behind the crossing are better for dinner than the main drag.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-shibuya-sky']::text[], array[]::text[], array['city.shibuya.tokyo.jp']::text[], 'draft'),
  ('tky-shibuya-sky', 'tokyo-city', 'Shibuya Sky', '渋谷スカイ', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7022, 35.6584), 4326)::extensions.geography, 'shibuya', 2, array['popculture']::interest_tag[], 0.15, 0.8, 0.1, 0.7, null, 45, 60, 90, array['after 17:30']::text[], 'Tickets go on sale online at midnight Japan time, 14 days ahead, and sunset slots go first; morning slots rarely sell out.', array[]::text[], array[]::text[], 'An open-air roof 229 m above the crossing. Bags go in lockers and strong wind closes the roof deck. Book the slot just before sunset and stay for the lights; tickets before 15:00 cost less, and online is cheaper than the counter.', 3400, 'recommended', 14, '10:00', '22:30', false, array[]::int[], array['tky-skytree']::text[], array['tky-shibuya-crossing']::text[], array[]::text[], array['shibuya-scramble-square.com']::text[], 'draft'),
  ('tky-shimokitazawa', 'tokyo-city', 'Shimokitazawa', '下北沢', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(139.668, 35.6615), 4326)::extensions.geography, 'shimokitazawa', 1, array['shopping', 'nightlife', 'offbeat']::interest_tag[], 0.25, 0.5, 0.5, 0.4, null, 30, 120, 180, array[]::text[], 'Busy at weekends; shops open late, so mornings are dead.', array[]::text[], array[]::text[], 'Vintage clothes, small live-music venues, theatres and coffee. The rail line went underground and its old route is now a long strip of shops and green space. Come after noon.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-gotokuji']::text[], array[]::text[], array['odakyu.jp']::text[], 'draft'),
  ('tky-gotokuji', 'tokyo-city', 'Gotoku-ji', '豪徳寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(139.6474, 35.6484), 4326)::extensions.geography, 'miyanosaka', 5, array['shrines', 'offbeat', 'popculture']::interest_tag[], 0.2, 0.4, 0.6, 0.4, null, 20, 40, 60, array[]::text[], 'A steady trickle for the cats; quiet otherwise.', array[]::text[], array[]::text[], 'Shelves of thousands of white beckoning-cat figures, left by people whose wishes came true — the temple claims to be where the maneki-neko began. Miyanosaka on the little Setagaya Line is closest; from Shimokitazawa, take the Odakyu Line to Gotokuji station and walk fifteen minutes.', 0, 'none', null, '06:00', '17:00', false, array[]::int[], array[]::text[], array['tky-shimokitazawa']::text[], array[]::text[], array['gotokuji.jp']::text[], 'draft'),
  ('tky-shinjuku-gyoen', 'tokyo-city', 'Shinjuku Gyoen', '新宿御苑', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(139.71, 35.6852), 4326)::extensions.geography, 'shinjuku-gyoemmae', 5, array['nature']::interest_tag[], 0.3, 0.6, 0.2, 0.6, null, 30, 90, 150, array[]::text[], 'Spacious all year. On the busiest cherry-blossom days entry can need a timed ticket booked online; check that spring''s notice.', array[]::text[], array[]::text[], 'French, English and Japanese gardens in one, and alcohol is banned — the calm hanami spot. Closing time moves with the season and last entry is half an hour before it. Closed on Mondays except in the cherry-blossom and autumn-colour weeks, when it opens every day.', 500, 'none', null, '09:00', '16:30', true, array[1]::int[], array[]::text[], array[]::text[], array['sakura', 'koyo']::text[], array['env.go.jp']::text[], 'draft'),
  ('tky-omoide-yokocho', 'tokyo-city', 'Omoide Yokocho', '思い出横丁', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(139.6996, 35.6929), 4326)::extensions.geography, 'shinjuku', 2, array['food', 'nightlife']::interest_tag[], 0.1, 0.8, 0.2, 0.5, null, 20, 60, 90, array['after 17:30']::text[], 'Tour groups shuffle through from seven to nine; seats free up fast.', array[]::text[], array[]::text[], 'Yakitori smoke in a narrow lane by the tracks at Shinjuku''s west exit. Most counters seat under ten, some charge a small seat fee, and some ask you not to photograph.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-golden-gai', 'tky-tocho']::text[], array[]::text[], array['shinjuku-omoide.com']::text[], 'draft'),
  ('tky-golden-gai', 'tokyo-city', 'Shinjuku Golden Gai', '新宿ゴールデン街', 'street', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7046, 35.694), 4326)::extensions.geography, 'shinjuku', 8, array['nightlife', 'offbeat']::interest_tag[], 0.1, 0.6, 0.3, 0.5, null, 30, 90, 180, array['after 17:30']::text[], 'Quiet before nine; the six alleys fill late and stay full past midnight.', array[]::text[], array[]::text[], 'Around 280 bars the size of a lift, each with its own crowd. Many charge a cover of ¥500–1,500 and say on the door whether visitors are welcome. Bars stay open into the small hours. Don''t photograph in the alleys.', 0, 'none', null, '19:00', '23:59', false, array[]::int[], array[]::text[], array['tky-omoide-yokocho']::text[], array[]::text[], array['goldengai.jp']::text[], 'draft'),
  ('tky-tocho', 'tokyo-city', 'Tokyo Metropolitan Government Building', '東京都庁', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(139.6922, 35.6896), 4326)::extensions.geography, 'tochomae', 3, array['popculture', 'offbeat']::interest_tag[], 0.1, 0.4, 0.3, 0.4, null, 20, 40, 60, array[]::text[], 'Short lift queues; worst on weekend afternoons.', array[]::text[], array[]::text[], 'Free observation decks 202 m up, ten minutes'' walk from Shinjuku Station. On clear winter mornings Mount Fuji shows. After dark the building''s own facade becomes a projection-mapping show. The South deck is the one open in the evening; each deck closes on a couple of days a month, so check the calendar.', 0, 'none', null, '09:30', '22:00', false, array[]::int[], array[]::text[], array['tky-omoide-yokocho']::text[], array[]::text[], array['zaimu.metro.tokyo.lg.jp']::text[], 'draft'),
  ('tky-nakano-broadway', 'tokyo-city', 'Nakano Broadway', '中野ブロードウェイ', 'shopping', extensions.ST_SetSRID(extensions.ST_MakePoint(139.6656, 35.709), 4326)::extensions.geography, 'nakano', 5, array['popculture', 'shopping', 'offbeat']::interest_tag[], 0.2, 0.4, 0.6, 0.4, null, 30, 90, 180, array[]::text[], 'The narrow corridors get busy at weekends.', array[]::text[], array[]::text[], 'A 1966 apartment block whose lower floors became a collectors'' mall: dozens of Mandarake shops, vintage toys, watches, idol photos. Shabbier and cheaper than Akihabara. Many shops open at noon.', 0, 'none', null, '12:00', '20:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['nakano-broadway.com']::text[], 'draft'),
  ('tky-imperial-east-garden', 'tokyo-city', 'Imperial Palace East Gardens', '皇居東御苑', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(139.758, 35.687), 4326)::extensions.geography, 'otemachi', 5, array['history', 'nature']::interest_tag[], 0.3, 0.4, 0.2, 0.5, null, 30, 60, 90, array[]::text[], 'Roomy; it is big and free.', array[]::text[], array[]::text[], 'Free, on the site of Edo Castle''s inner citadel — the great stone base of the vanished keep is still there. Usually closed Mondays and Fridays; closing time moves with the season. The palace grounds are seen only on a separate free guided walk, booked ahead or joined on the day while places last, and it doesn''t go inside the buildings.', 0, 'none', null, '09:00', '16:00', true, array[1, 5]::int[], array[]::text[], array['tky-tokyo-station']::text[], array[]::text[], array['kunaicho.go.jp']::text[], 'draft'),
  ('tky-tokyo-station', 'tokyo-city', 'Tokyo Station & Marunouchi', '東京駅 丸の内駅舎', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7671, 35.6812), 4326)::extensions.geography, 'tokyo', 1, array['history', 'shopping']::interest_tag[], 0.15, 0.6, 0.2, 0.4, null, 15, 45, 90, array[]::text[], 'Commuters at rush hour; easy the rest of the day.', array[]::text[], array[]::text[], 'The 1914 red-brick station, restored with its domes. The free roof garden of the KITTE building opposite has the best view of it. Underground, Ramen Street and Character Street.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-imperial-east-garden']::text[], array[]::text[], array['tokyostationcity.com']::text[], 'draft'),
  ('tky-ginza', 'tokyo-city', 'Ginza', '銀座', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7649, 35.6717), 4326)::extensions.geography, 'ginza', 1, array['shopping', 'food']::interest_tag[], 0.25, 0.6, 0.1, 0.5, null, 30, 90, 180, array[]::text[], 'Busy at weekends but well spread out.', array[]::text[], array[]::text[], 'On weekend afternoons Chuo-dori closes to cars and becomes a promenade. Itoya for stationery, the department-store food halls in the basements, and the free roof garden on GINZA SIX.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-kabukiza', 'tky-tsukiji-outer']::text[], array[]::text[], array['ginza.jp']::text[], 'draft'),
  ('tky-kabukiza', 'tokyo-city', 'Kabuki-za', '歌舞伎座', 'performance', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7678, 35.6695), 4326)::extensions.geography, 'higashi-ginza', 1, array['history', 'art']::interest_tag[], 0.15, 0.5, 0.3, 0.6, null, 60, 90, 240, array[]::text[], 'Single-act seats for popular months go fast; the rest are rarely full.', array[]::text[], array[]::text[], 'Single-act tickets on the fourth floor let you see one act for a fraction of a full programme — the right way to try kabuki. They go on sale online at noon the day before, priced by act. English captions come on a device you rent at the theatre. Times follow the month''s programme, with a few dark days between runs.', 1500, 'recommended', 1, '11:00', '21:00', false, array[]::int[], array[]::text[], array['tky-ginza']::text[], array[]::text[], array['kabuki-za.co.jp']::text[], 'draft'),
  ('tky-tsukiji-outer', 'tokyo-city', 'Tsukiji Outer Market', '築地場外市場', 'market', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7707, 35.6654), 4326)::extensions.geography, 'tsukiji', 2, array['food']::interest_tag[], 0.2, 0.85, 0.1, 0.7, null, 30, 75, 120, array['before 10:00']::text[], 'Shoulder to shoulder from ten; by two most stalls have shut.', array[]::text[], array[]::text[], 'The wholesale fish market moved to Toyosu in 2018; this is the retail fringe that stayed — tamagoyaki, grilled scallops, sushi breakfasts. Eat at the stall rather than walking. Earlier hours are for trade buyers. Each shop has its own days off: many close on Sundays, holidays and Wednesdays, though about a third open on Sundays.', 0, 'none', null, '09:00', '14:00', false, array[]::int[], array[]::text[], array['tky-tsukiji-honganji', 'tky-hamarikyu']::text[], array[]::text[], array['tsukiji.or.jp']::text[], 'draft'),
  ('tky-tsukiji-honganji', 'tokyo-city', 'Tsukiji Hongan-ji', '築地本願寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7724, 35.6664), 4326)::extensions.geography, 'tsukiji', 1, array['shrines', 'history', 'offbeat']::interest_tag[], 0.1, 0.3, 0.6, 0.4, null, 15, 30, 60, array[]::text[], 'Never busy.', array[]::text[], array[]::text[], 'A 1934 temple in the style of ancient India, with a pipe organ inside the main hall. The café on site serves a breakfast of eighteen small dishes. A minute from the outer market.', 0, 'none', null, '06:00', '16:00', false, array[]::int[], array[]::text[], array['tky-tsukiji-outer']::text[], array[]::text[], array['tsukijihongwanji.jp']::text[], 'draft'),
  ('tky-hamarikyu', 'tokyo-city', 'Hama-rikyu Gardens', '浜離宮恩賜庭園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7633, 35.66), 4326)::extensions.geography, 'shiodome', 7, array['nature', 'history']::interest_tag[], 0.3, 0.3, 0.4, 0.5, null, 30, 60, 90, array[]::text[], 'Spacious; never crowded.', array[]::text[], array[]::text[], 'A shogun''s duck-hunting garden with a seawater pond and a teahouse on an island (matcha and a sweet extra), the Shiodome towers rising behind. Some water buses from Asakusa stop here, but only to let people off, so leave on foot. Last entry 16:30.', 300, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['tky-tsukiji-outer']::text[], array[]::text[], array['tokyo-park.or.jp']::text[], 'draft'),
  ('tky-tsukishima', 'tokyo-city', 'Tsukishima Monja Street', '月島もんじゃストリート', 'food', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7826, 35.6633), 4326)::extensions.geography, 'tsukishima', 2, array['food']::interest_tag[], 0.1, 0.4, 0.5, 0.4, null, 60, 90, 120, array['after 17:30']::text[], 'Queues at the famous places on weekend evenings; plenty of others with seats.', array[]::text[], array[]::text[], 'Dozens of restaurants making monjayaki, Tokyo''s runny cousin of okonomiyaki, cooked on the hotplate at your table and eaten off a tiny spatula. Staff will show you the first one. Some open for lunch, but many only from 17:00 on weekdays.', 0, 'none', null, '17:00', '22:00', false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['monja.gr.jp']::text[], 'draft'),
  ('tky-toyosu-market', 'tokyo-city', 'Toyosu Market', '豊洲市場', 'market', extensions.ST_SetSRID(extensions.ST_MakePoint(139.785, 35.6455), 4326)::extensions.geography, 'shijo-mae', 1, array['food', 'offbeat']::interest_tag[], 0.25, 0.4, 0.4, 0.5, null, 30, 60, 120, array['before 08:00']::text[], 'The sushi counters inside queue from five in the morning; the galleries are calm.', array[]::text[], array[]::text[], 'The tuna auction runs from about 05:30 and is watched from glass galleries above; the close-up lower deck is by online lottery a month ahead. The restaurants and shops close well before the galleries. Closed Sundays, holidays and some Wednesdays.', 0, 'none', null, '05:00', '17:00', false, array[0]::int[], array[]::text[], array['tky-senkyaku-banrai', 'tky-teamlab-planets']::text[], array[]::text[], array['shijou.metro.tokyo.lg.jp']::text[], 'draft'),
  ('tky-senkyaku-banrai', 'tokyo-city', 'Toyosu Senkyaku Banrai', '豊洲 千客万来', 'food', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7835, 35.6464), 4326)::extensions.geography, 'shijo-mae', 1, array['food', 'onsen']::interest_tag[], 0.15, 0.6, 0.4, 0.4, null, 30, 60, 180, array[]::text[], 'Busy at lunch and weekends; easy in the afternoon.', array[]::text[], array[]::text[], 'An Edo-style food street next to Toyosu Market, opened in 2024, with a hot-spring spa on the floors above. The free footbath looking over the bay is on the eighth floor; the rooftop one is for spa guests. Shops shut at 18:00 and most restaurants at 20:00. Prices are pitched at visitors.', 0, 'none', null, '10:00', '20:00', false, array[]::int[], array[]::text[], array['tky-toyosu-market']::text[], array[]::text[], array['toyosu-senkyakubanrai.jp']::text[], 'draft'),
  ('tky-teamlab-planets', 'tokyo-city', 'teamLab Planets', 'チームラボプラネッツ', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7898, 35.6492), 4326)::extensions.geography, 'shin-toyosu', 1, array['art', 'popculture']::interest_tag[], 0.3, 0.7, 0.1, 0.6, null, 60, 90, 120, array[]::text[], 'Timed entry keeps it moving; weekend and holiday slots sell out.', array[]::text[], array[]::text[], 'You walk barefoot through knee-deep water in some rooms — wear something that rolls up above the knee. Prices and hours change by day, with a few maintenance closures; it is set to run until 2027. Pick this or Borderless, not both.', 3800, 'required', 7, '09:00', '22:00', true, array[]::int[], array['tky-teamlab-borderless']::text[], array['tky-toyosu-market']::text[], array[]::text[], array['teamlab.art']::text[], 'draft'),
  ('tky-teamlab-borderless', 'tokyo-city', 'teamLab Borderless', 'チームラボボーダレス', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7403, 35.6605), 4326)::extensions.geography, 'kamiyacho', 3, array['art', 'popculture']::interest_tag[], 0.3, 0.7, 0.1, 0.6, null, 60, 120, 180, array[]::text[], 'Timed entry, but the popular rooms still queue inside.', array[]::text[], array[]::text[], 'Moved from Odaiba to Azabudai Hills in 2024. Rooms with no map that bleed into each other; plan two hours. Prices and hours change by day, with a few closed days. Pick this or Planets, not both.', 3400, 'required', 7, '09:00', '21:00', true, array[]::int[], array['tky-teamlab-planets']::text[], array[]::text[], array[]::text[], array['teamlab.art']::text[], 'draft'),
  ('tky-odaiba', 'tokyo-city', 'Odaiba waterfront', 'お台場', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7752, 35.629), 4326)::extensions.geography, 'odaiba-kaihinkoen', 3, array['popculture', 'nature']::interest_tag[], 0.3, 0.5, 0.2, 0.4, null, 30, 90, 180, array['after 17:30']::text[], 'Families at weekends; quiet on weekday evenings.', array[]::text[], array[]::text[], 'Ride the driverless Yurikamome over the Rainbow Bridge loop, then walk the beach for the bridge and skyline at dusk. The life-size Gundam outside DiverCity left at the end of August 2026, and the big Ferris wheel and VenusFort are gone too.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['gotokyo.org']::text[], 'draft'),
  ('tky-tokyo-tower', 'tokyo-city', 'Tokyo Tower', '東京タワー', 'viewpoint', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7454, 35.6586), 4326)::extensions.geography, 'akabanebashi', 5, array['popculture', 'history']::interest_tag[], 0.15, 0.5, 0.05, 0.5, null, 30, 60, 90, array['after 17:30']::text[], 'Short queues except weekend evenings.', array[]::text[], array[]::text[], 'Better to look at than from: the classic view is of the lit tower from Zojo-ji or Shiba Park. The Main Deck is enough; the Top Deck is a pricier booked tour.', 1500, 'none', null, '09:00', '23:00', false, array[]::int[], array[]::text[], array['tky-zojoji']::text[], array[]::text[], array['tokyotower.co.jp']::text[], 'draft'),
  ('tky-zojoji', 'tokyo-city', 'Zojo-ji', '増上寺', 'temple', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7483, 35.6575), 4326)::extensions.geography, 'onarimon', 3, array['shrines', 'history']::interest_tag[], 0.15, 0.4, 0.3, 0.5, null, 20, 40, 60, array[]::text[], 'Calm except at New Year.', array[]::text[], array[]::text[], 'The Tokugawa shoguns'' family temple, with Tokyo Tower rising behind the main hall — the photograph. In the garden, rows of small stone jizo in knitted red caps hold spinning pinwheels. The great main gate is under a restoration expected to last about ten years from 2025.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-tokyo-tower']::text[], array[]::text[], array['zojoji.or.jp']::text[], 'draft'),
  ('tky-mori-art', 'tokyo-city', 'Mori Art Museum', '森美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7292, 35.6604), 4326)::extensions.geography, 'roppongi', 5, array['art']::interest_tag[], 0.2, 0.4, 0.3, 0.5, null, 60, 90, 150, array[]::text[], 'Weekend afternoons are busiest; weekday mornings are calm.', array[]::text[], array[]::text[], 'Contemporary art on the 53rd floor of Roppongi Hills; the Tokyo City View deck below is a separate or combined ticket. Timed tickets online. Open late most nights but closes early on Tuesdays, and closed between exhibitions, with a long renovation planned from September 2027 to April 2028.', 2600, 'recommended', null, '10:00', '17:00', true, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['mori.art.museum']::text[], 'draft'),
  ('tky-akihabara', 'tokyo-city', 'Akihabara', '秋葉原', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7713, 35.6995), 4326)::extensions.geography, 'akihabara', 1, array['popculture', 'shopping']::interest_tag[], 0.3, 0.7, 0.05, 0.7, null, 30, 120, 240, array[]::text[], 'Sunday afternoons, when Chuo-dori closes to cars, are the busiest.', array[]::text[], array[]::text[], 'Retro games, figures, gachapon halls and maid cafés. The shops stack upward — the good ones are on the fourth floor, not at street level.', 0, 'none', null, '11:00', '20:00', false, array[]::int[], array[]::text[], array['tky-kanda-myojin']::text[], array[]::text[], array['keishicho.metro.tokyo.lg.jp']::text[], 'draft'),
  ('tky-kanda-myojin', 'tokyo-city', 'Kanda Myojin', '神田明神', 'shrine', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7679, 35.7021), 4326)::extensions.geography, 'akihabara', 8, array['shrines', 'popculture']::interest_tag[], 0.1, 0.3, 0.5, 0.4, null, 15, 30, 45, array[]::text[], 'Quiet, except early January when Tokyo''s offices come to pray for the year''s business.', array[]::text[], array[]::text[], 'A shrine founded in 730 that sells charms to protect your electronics. Anime fans leave drawn ema plaques. Ten minutes uphill from Akihabara.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-akihabara']::text[], array[]::text[], array['kandamyoujin.or.jp']::text[], 'draft'),
  ('tky-koishikawa-korakuen', 'tokyo-city', 'Koishikawa Korakuen', '小石川後楽園', 'garden', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7497, 35.7056), 4326)::extensions.geography, 'iidabashi', 8, array['nature', 'history']::interest_tag[], 0.25, 0.3, 0.5, 0.4, null, 30, 60, 90, array[]::text[], 'Calm except for autumn-colour weekends.', array[]::text[], array[]::text[], 'One of Tokyo''s oldest daimyo gardens, begun in 1629, with a stone full-moon bridge — next door to Tokyo Dome, so a rollercoaster sometimes screams over the trees. Last entry 16:30.', 300, 'none', null, '09:00', '17:00', false, array[]::int[], array[]::text[], array['tky-kagurazaka']::text[], array['koyo']::text[], array['tokyo-park.or.jp']::text[], 'draft'),
  ('tky-kagurazaka', 'tokyo-city', 'Kagurazaka', '神楽坂', 'district', extensions.ST_SetSRID(extensions.ST_MakePoint(139.7405, 35.7022), 4326)::extensions.geography, 'iidabashi', 3, array['food', 'history', 'offbeat']::interest_tag[], 0.2, 0.3, 0.6, 0.4, null, 30, 75, 150, array['after 17:30']::text[], 'Local diners, not tour groups.', array[]::text[], array[]::text[], 'A slope of bistros and izakaya with stone-paved alleys of old geisha houses running off it — a little Kyoto at a fraction of the crowd. Best for dinner.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array['tky-koishikawa-korakuen']::text[], array[]::text[], array['gotokyo.org']::text[], 'draft'),
  ('tky-ghibli', 'tokyo-city', 'Ghibli Museum', '三鷹の森ジブリ美術館', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.5704, 35.6962), 4326)::extensions.geography, 'mitaka', 15, array['art', 'popculture']::interest_tag[], 0.25, 0.6, 0.2, 0.7, null, 60, 120, 180, array[]::text[], 'Timed entry; inside it is busy but never a queue.', array[]::text[], array[]::text[], 'Tickets only in advance for a set entry time, released at 10:00 Japan time on the 10th of the month before and gone fast; none at the door. Also closed for maintenance a few weeks a year. No photos inside. Walk through Inokashira Park from Kichijoji to get there.', 1000, 'required', null, '10:00', '18:00', false, array[2]::int[], array[]::text[], array[]::text[], array[]::text[], array['ghibli-museum.jp']::text[], 'draft'),
  ('tky-harry-potter', 'tokyo-city', 'Warner Bros. Studio Tour Tokyo', 'ワーナー ブラザース スタジオツアー東京', 'museum', extensions.ST_SetSRID(extensions.ST_MakePoint(139.6487, 35.7434), 4326)::extensions.geography, 'toshimaen', 2, array['popculture']::interest_tag[], 0.4, 0.6, 0.2, 0.5, null, 180, 240, 300, array[]::text[], 'Timed entry; the Great Hall and Diagon Alley are busiest mid-morning.', array[]::text[], array[]::text[], 'The Making of Harry Potter: sets, costumes and props on the old Toshimaen site. Timed tickets online only, priced by date; allow four hours. Fans love it; for everyone else the day is better spent elsewhere.', 6300, 'required', 14, '08:30', '22:00', true, array[]::int[], array[]::text[], array[]::text[], array[]::text[], array['wbstudiotour.jp']::text[], 'draft'),
  ('tky-takao', 'tokyo-city', 'Mount Takao', '高尾山', 'hike', extensions.ST_SetSRID(extensions.ST_MakePoint(139.27, 35.6323), 4326)::extensions.geography, 'takaosanguchi', 5, array['nature', 'shrines']::interest_tag[], 0.6, 0.7, 0.3, 0.5, 0.55, 120, 240, 360, array['before 09:00']::text[], 'November weekends are among the busiest trails in the world. Weekdays are pleasant.', array[]::text[], array['limited_mobility']::text[], 'Fifty minutes from Shinjuku on the Keio line. A cable car or chairlift takes you halfway, then Yakuo-in temple and the summit, with Fuji on clear winter days. Trail 1 is paved; the others are real paths.', 0, 'none', null, null, null, false, array[]::int[], array[]::text[], array[]::text[], array['koyo']::text[], array['takaotozan.co.jp']::text[], 'draft')
